template< typename T >
using Edges = vector< edge< T > >;
template< typename T >
using WG = vector< Edges< T > >;
using UWG = vector< vector <int> >;

UWG g;
int N;
void ans(int cur){
  each(e ,g[cur]){
    out(cur , e);
    ans(e);
  }
}

int dfs(int src, int sum,int dst){
  trc(src,sum,dst);
  each(e,g[src]){
    int cursum = sum ^ ( (int(e)) % N);
    int cur_e = e;
    trc(cur_e,cursum);
    if(cursum == dst){
      return cur_e;
    }
    while(!g[cur_e].empty()){
      trc(cur_e,cursum);
      cur_e = g[cur_e][0];
      cursum = cursum ^ ( (int(cur_e)) % N);
      if(cursum == dst){
        return cur_e;
      }
    }
  }
  return -1;
}

