  g[3].pb(N + 1);
  g[N + 1].pb(N + 2);
  g[N + 2].pb(N + 3);
  int cur = 3;
  trc("hoge");
  while( cur + 4 <= N ){
    g[1].pb(cur + 1);
    g[cur + 1].pb(cur + 2);
    g[cur + 2].pb(cur + 3);
    g[cur + 3].pb(cur + 4);
    g[cur + 4].pb(cur + 1 + N);
    g[cur + 1 + N].pb(cur + 2 + N);
    g[cur + 2 + N].pb(cur + 3 + N);
    g[cur + 3 + N].pb(cur + 4 + N);
    cur = cur + 4;
  }
  // たとえば11まで書いた...頭は8か9
  // hoge = 11
  trc("hogehoge",cur);
  int hoge = cur; 
  if(hoge == N){}
  else if(N % 4){
    g[1].pb(hoge + 1);
    g[hoge + 1].pb(hoge + 2);
    g[1].pb(hoge + 2 + N);
    g[hoge + 2 + N].pb(hoge + 1 + N);
    if(N % 4 == 2){
      g[hoge + 2 + N].pb(hoge  + 3 + N);
      g[2].pb(hoge + 3);
    }
  }
  else{
    g[1].pb(hoge + 1);
    int ret = dfs(1 , hoge - 3, hoge + 1);
    if(ret == -1) exit(1);
    trc(ret);
    g[ret].pb(hoge + 1 + N);
  }
  /*
  while(cur + 1 <= N){
