		return 0;
	}
	int two = 1;
	while (two < N)two *= 2;
	if (two == N) {
		cout << "No" << endl;
		return 0;
	}
	two /= 2;
	auto f = [&](int i, int j) {return i + j * N; };
	vector < pair<int, int>>ans;
