			con(f(x + 0, 0), f(res + 0, 0));
			con(f(x + 1, 1), f(res + 1, 0));
		}
		else {
			con(f(x, 0), f(x + 1, 0));
			con(f(x, 1), f(x + 1, 1));
			con(f(x + 0, 0), f(1, 0));
			con(f(x + 1, 1), f(1, 0));
		}
	}
	if (N % 2 == 0) {
		int res = N - two;
		con(f(two + 0, 0), f(N, 0));
		con(f(N, 1), f(res + 0, 0));
	}
	cout << "Yes" << endl;
	for (auto p : ans) {
		cout << p.first << " " << p.second << endl;
	}
	return 0;
}

