void Con(int n) {
  Edge(1, 2);
  Edge(2, 3);
  Edge(3, n + 1);
  Edge(n + 1, n + 2);
  Edge(n + 2, n + 3);
  for (int t = 4; t < n; t += 2) {
    Edge(n + 1, t);
    Edge(t, t + 1);
    Edge(n + 1, n + t + 1);
    Edge(n + t + 1, n + t);
  }
}

