  Con(n - !(n & 1));
  if (~n & 1) {
    int k = 0;
    while ((1 << k + 1) < n) {
      ++k;
    }
    Edge(n, 1 << k);
    Edge(n - (1 << k), 2 * n - (2 * n - (1 << k) + 1));
  }
  return 0;
}

