  add_edge(N + 1, N + 2);
  add_edge(N + 2, 3);
  add_edge(3, 1);
  add_edge(1, 2);
  add_edge(2, 3 + N);
  for (auto i = 4; i + 1 <= N; i += 2)
  {
    add_edge(1, i);
    add_edge(i, i + 1 + N);
