    setIO();

    int N; re(N);

    if (__builtin_popcount(N) == 1) {
        ps("No");
        return 0;
    }

    int every = 0;
    F0R (v, N + 1) every ^= v;

    if (every == 0) {
        ps("Yes");
        F0R (i, 2 * N - 1)
            ps(i+1, i+2);
        return 0;
    }

    assert(every == 1 || every == N || every == N + 1);

    vi need, rest;

    FOR (v, 1, N + 1) {
        if (v == 1 && (every == 1 || every == N + 1)) continue;
        if (v == N && (every == N || every == N + 1)) continue;
        if (every > 1 && __builtin_popcount(v) == 1 && (N & v)) need.pb(v);
        else rest.pb(v);
    }

    if (every == 1) {
        ps("Yes");
        F0R (i, sz(rest) - 1) {
            ps(rest[i], rest[i+1]);
            ps(N + rest[i], N + rest[i+1]);
        }
        ps(rest.back(), N + rest.front());
        ps(1, 2);
        ps(3, N + 1);
        return 0;
    }

    reverse(all(need));
    vi comb = need;
    comb.insert(comb.end(), all(rest));

    int made = 0; trav (v, need) made |= v;
    if (made == N) {
        ps("Yes");
        F0R (i, sz(comb) - 1) {
            ps(comb[i], comb[i+1]);
            ps(N + comb[i], N + comb[i+1]);
        }
        ps(comb.back(), N + comb.front());
        ps(N, need.front());
        ps(need.back(), 2 * N);
        return 0;
    } else {
        assert(false);
        return 0;
    }

    return 0;
}

