int N;
void solve(int n)
{
	report(1,2);
	report(2,3);
	report(3,1+N);
	report(1+N,2+N);
	report(2+N,3+N);
	for(int i=4;i<=n;i+=2)
	{
		report(1+N,i+N);
		report(i+N,i+1+N);
		report(1+N,i+1);
		report(i+1,i);
	}
}
