vector<pii> getOdd(int k, int n){
	// 2 * k + 1
	vector<pii> ret;
	for(int i = 1; i <= k; i++){
		ret.push_back({1, 2 * i});
		ret.push_back({1, 2 * i + 1});
		ret.push_back({2 * i, n + 2 * i + 1});
		ret.push_back({2 * i + 1, n + 2 * i});
	}
	ret.push_back({n + 2, n + 1});
	return ret;
}

int main(){
	int n; cin >> n;
	int k = 0; while((1 << k) < n) k++;
	if((1 << k) == n){
		printf("No\n");
		return 0;
	}
	vector<pii> edges = getOdd(n & 1 ? n / 2 : n / 2 - 1, n);
	if(!(n & 1)){
		for(int r = 0; r < k; r++) if((n/2) >> r & 1){
			int p = (1 << r), q = (n/2) ^ p;
			trace(p, q);
			edges.push_back({n, 2 * p});
			edges.push_back({2 * n, 2 * q + 1});
			break;
		}
	}
	printf("Yes\n");
	printf("%d\n", sz(edges));
	for(auto it : edges) printf("%d %d\n", it.F, it.S);
}

