int get2(int a) {
	int cnt = 0;
	while ((1 << cnt) <= a) cnt++;
	return cnt - 1;
}

struct UnionFind {
	vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

	UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
		for (int i = 0; i < N; i++) par[i] = i;
	}

	int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
		if (par[x] == x) return x;
		return par[x] = root(par[x]);
	}

	void unite(int x, int y) { // xとyの木を併合
		int rx = root(x); //xの根をrx
		int ry = root(y); //yの根をry
		if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
		par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
	}

	bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
};

int main() {

	cin >> N;
	for (int i = 0; i < 20; i++) {
		if (N == (1 << i)) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;

	UnionFind uf(2 * N + 1);

	cout << 1 << " " << 2 << endl;
	uf.unite(1, 2);

	for (int i = 2; i <= N; i++) {
		if (i == (1 << get2(i))) {
			if (!uf.same(i, i + 1)) {
				cout << i << " " << i + 1 << endl;
				uf.unite(i, i + 1);
			}
			if (!uf.same(i + 1, N + 1)) {
				cout << i + 1 << " " << N + 1 << endl;
				uf.unite(i + 1, N + 1);
			}
			if (!uf.same(N + 1, N + i)) {
				cout << N + 1 << " " << N + i << endl;
				uf.unite(N + 1, N + i);
			}
		}
		else {
			if (!uf.same(i, i - (1 << get2(i)) + N)) {
				cout << i << " " << i - (1 << get2(i)) + N << endl;
				uf.unite(i, i - (1 << get2(i)) + N);
			}
			if (!uf.same(i - (1 << get2(i)) + N, N + (1 << get2(i)))) {
				cout << i - (1 << get2(i)) + N << " " << N + (1 << get2(i)) << endl;
				uf.unite(i - (1 << get2(i)) + N, N + (1 << get2(i)));
			}
			if (!uf.same(N + (1 << get2(i)), i + N)) {
				cout << N + (1 << get2(i)) << " " << i + N << endl;
				uf.unite(N + (1 << get2(i)), i + N);
			}
		}
	}

	return 0;
}

