        if ((n >> bit) & 1) {
            out(last, cur);
            for (int i = cur; i < cur + (1 << bit) - 1; ++i) {
                out(i, i + 1);
            }
            out(cur + (1 << bit) - 1, n + cur);
            for (int i = cur; i < cur + (1 << bit) - 1; ++i) {
                out(n + i, n + i + 1);
            }
            last = n + cur + (1 << bit) - 1;
            cur += (1 << bit) - 1;
        }
    }
    return 0;
}

