const int NMAX = 1000;
vector <int> adia[NMAX];
int n;

void dfs(int nod, int tata, int xact, int root)
{
	if (nod == root + n) {
		if (xact != root) {
			cerr << "Prost pentru radacina " << root << '\n';
			exit(0);
		}
		return;
	}
	for (auto i : adia[nod])
		if (i != tata)
			dfs(i, nod, (xact ^ (nod > n ? nod - n : nod)), root);
}

