#include <bits/stdc++.h>
using namespace std;
using lint = long long;
using pi = pair<int, int>;
const int MAXN = 200005;

struct disj{
	int pa[MAXN];
	void init(int n){
		iota(pa, pa + n + 1, 0);
	}
	int find(int x){
		return pa[x] = (pa[x] == x ? x : find(pa[x]));
	}
	bool uni(int p, int q){
		p = find(p); q = find(q);
		if(p == q)return 0;
		pa[q] = p; return 1;
	}
}disj;

int n;
vector<int> gph[MAXN];
vector<pi> edg;
int par[18][MAXN], prec[MAXN], dep[MAXN];

int lca(int s, int e){
	if(dep[s] > dep[e]) swap(s, e);
	int dx = dep[e] - dep[s];
	for(int i=0; i<18; i++){
		if((dx >> i) & 1) e = par[i][e];
	}
	for(int i=17; i>=0; i--){
		if(par[i][s] != par[i][e]){
			s = par[i][s];
			e = par[i][e];
		}
	}
	if(s != e) return par[0][s];
	return s;
}

void dfs(int x, int p){
	for(auto &i : gph[x]){
		if(i != p){
			dep[i] = dep[x] + 1;
			par[0][i] = x;
			prec[i] = prec[x] ^ (i > n ? (i-n) : i);
			dfs(i, x);
		}
	}
}
void add_edge(int s, int e){
	assert(1 <= s && s <= 2 * n);
	assert(1 <= e && e <= 2 * n);
	assert(disj.uni(s, e));
	edg.emplace_back(s, e);
	gph[s].push_back(e);
	gph[e].push_back(s);
}

int main(){
	cin >> n;
	if((n & -n) == n){
		puts("No");
		return 0;
	}
	if(n == 3){
		puts("Yes");
		for(int i=2; i<=n+n; i++) printf("%d %d\n", i-1, i);
		return 0;
	}
	disj.init(n + n);
	int N = (n - 1) / 4;
	for(int i=1; i<=4*N-1; i++){
		if(i != 4 * N - 1){
			add_edge(i, i + 1);
			add_edge(i + n, i + n + 1);
		}
		else{
			add_edge(4 * N - 1, n + 1);
		}
	}
	if(4 * N + 1 <= n){
		add_edge(4 * N + 1, 1);
		add_edge(4 * N, 4 * N + 1);

		add_edge(1, 4 * N + n);
		add_edge(4 * N + n, 4 * N + 1 + n);
	}
	if(4 * N + 2 <= n){
		add_edge(4 * N + 1, 4 * N + 2);
		add_edge(2, 4 * N + 2 + n);
	}
	if(4 * N + 3 <= n){
		add_edge(4 * N + 3, 4 * N + n);
		add_edge(2, 4 * N + 3 + n);
	}
	if(4 * N + 4 <= n){
		add_edge(4 * N + 4 + n, 4 * N + n);
		int w = (4 * N) ^ 1 ^ 2 ^ 3 ^ (4 * N + 4);
		add_edge(w, 4 * N + 4);
	}
	assert(edg.size() == n+n - 1);
	prec[1] = 1;
	dfs(1, 0);
	for(int i=1; i<18; i++){
		for(int j=1; j<=2*n; j++){
			par[i][j] = par[i-1][par[i-1][j]];
		}
	}
	for(int i=1; i<=n; i++){
		int l = lca(i, i + n);
		int ans = prec[i] ^ prec[i + n] ^ (l > n ? (l-n) : l);
		assert(ans == i);
	}
	puts("Yes");
	for(auto &i : edg) printf("%d %d\n", i.first, i.second);
}

