mt19937 rng(58);

int main(){

    int N;
    scanf("%d", &N);
    // __builtin_popcount関数: 整数N を 2進数表記した場合の, 1 の個数.
    if(__builtin_popcount(N) == 1){
        printf("%s\n", "No");
        return 0;
    }

    printf("%s\n", "Yes");
    vector<int> all(N);
    // 指定された値から始まる整数列を生成.
    // https://cpprefjp.github.io/reference/numeric/iota.html
    iota(all.begin(), all.end(), 1);
    int v = 0;
    for(int x : all) v ^= x;
    if(v == 0){
        for(int i = 1; i < 2 * N; i++) printf("%d %d\n", i, i + 1);
        return 0;
    }

    if(v <= N){
        all.erase(all.begin() + v - 1);
        while(true){
            shuffle(all.begin(), all.end(), rng);
            vector<int> pref(1, 0);
            for(int rot = 0; rot < 2; rot++){
                for(int i = 0; i < N - 1; i++){
                    pref.push_back(pref.back() ^ all[i]);
                }
            }
            map<int, int> mp;
            int from = -1, to = -1;
            for(int it = 0; it < (int)pref.size(); it++){
                int x = pref[it];
                if(mp.find(x ^ v) != mp.end()){
                    from = mp[x ^ v];
                    to = it;
                    break;
                }
                mp[x] = it;
            }
            if(from != -1){
                vector<int> vers;
                for(int i = 0; i < N - 1; i++) vers.push_back(all[i]);
                for(int i = 0; i < N - 1; i++) vers.push_back(all[i] + N);
                for(int i = 0; i < 2 * N - 3; i++) printf("%d %d\n", vers[i], vers[i + 1]);
                printf("%d %d\n", vers[from], v);
                printf("%d %d\n", vers[to - 1], v + N);
                break;
            }
        }
        return 0;
    }
    assert(v == N + 1);
    vector<int> vers;
    for(int i = 2; i <= N - 1; i++) vers.push_back(i);
    swap(vers[vers.size() - 2], vers[vers.size() - 1]);
    for(int i = 2; i <= N - 1; i++) vers.push_back(i + N);
    swap(vers[vers.size() - 2], vers[vers.size() - 1]);
    for(int i = 0; i < (int) vers.size() - 1; i++) printf("%d %d\n", vers[i], vers[i + 1]);
    printf("%d %d\n", N - 1, 1);
    printf("%d %d\n", N - 2, N + 1);
    printf("%d %d\n", N - 2, N);
    printf("%d %d\n", N + 2, N + N);
    return 0;

}

