      if(r == l)l++;
      else break;
    }
    int r = n ^ 1 ^ l;
    if(l % 2 == 0)edge[l].pb(n);
    else edge[l + n].pb(n);
    if(r % 2 == 0)edge[r].pb(2 * n);
    else edge[r + n].pb(2 * n);
  }
  FOR(i, 1, 2 * n + 1){
    for(auto e: edge[i]){
      cout << min(i, e) << " " << max(i, e) << "\n";
    }
  }
  cout << flush;
  return 0;
}

