    vector < int > res;
    int c = 0;
    for (int i = 0; i < p.size(); i++){
        p[i] += c;
        res.pb((p[i] * x % mod + mod) % mod);
        c = (y * (p[i] - c) % mod + mod) % mod;
    }
    res.pb(c);
    return res;
}
vector < int > dv(vector < int > p, int x, int y){
    vector < int > res;
    int c = 0;
    for (int i = 0; i < p.size() - 1; i++){
        p[i] += c;
        res.pb((p[i] % mod + mod) % mod);
        c = (-y * p[i] % mod + mod) % mod;
    }
    return res;
}
