int main(){
    int n;
    cin>>n;
    if(n<=2){
        No();
        return 0;
    }
    if(n==3){
        cout<<"Yes"<<endl;
        for(int i=0;i<5;i++){
            cout<<i+1<<" "<<i+2<<endl;
        }
        return 0;
    }
    int m=1;
    while(m*2<=n) m*=2;

    if(m==n){
        No();
        return 0;
    }
    vector<pair<int,int>> res;
    auto line=[n,&res](vector<int> vec){
        for(int i=0;i+1<vec.size();i++){
            res.push_back({vec[i],vec[i+1]});
        }
        for(int i=0;i+1<vec.size();i++){
            res.push_back({n+vec[i],n+vec[i+1]});
        }
    };
    for(int i=m;i+1<=n;i+=2){
        line({i,i+1});
        res.push_back({i,1});
        res.push_back({1,i+1+n});
    }
    if(n%2==0){
        int x=n^1^m;
        res.push_back({n,m});
        res.push_back({x,n+n});
        vector<int> vec(m-1);
        vec[0]=1;
        vec[1]=x;
        int id=2;
        for(int i=2;i<m;i++){
            if(i!=x) vec[id++]=i;
        }
        line(vec);
        res.push_back({vec.back(),n+1});
    }
    else{
        vector<int> vec(m-1);
        iota(vec.begin(),vec.end(),1);
        line(vec);
        res.push_back({m-1,n+1});
    }
    assert(res.size()==2*n-1);
    cout<<"Yes"<<endl;
    for(auto p:res){
        cout<<p.first<<" "<<p.second<<endl;
    }

    return 0;
}

