int main() {

  vector<int> squares = {1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536};

  int N = ii();

  for (auto eachsquare : squares){
    if (N == eachsquare){
      os("No"); br();
      return 0;
    }
  }

  os("Yes"); br();

  //3までを構築
  oi(1); oi(2); br();
  oi(2); oi(3); br();
  oi(3); oi(N+1); br();
  oi(N+1); oi(N+2); br();
  oi(N+2); oi(N+3); br();
  if(N==3){
    return 0;
  }
  //偶奇どちらでも行う構築
  //N-3を2で割って切り捨てた数（{n, n+1}の組の数）だけ行う
  REP(i, 0, (N-3)/2 ){
    int j = i*2;
    oi(4+j); oi(4+j+1); br();
    oi(4+j+1); oi(1); br();
    oi(1); oi(N+4+j); br();
    oi(N+4+j); oi(N+4+j+1); br();
  }

  //奇数
  if(N%2==1){
    return 0;
  }
  else{ //最後に残った偶数（N）の処理
    //残ったNは1, 任意の同じbit桁数の数(aとする), そしてbと繋ぐ
    //aが決まれば、bは一意に定まる(b = )
    //Nは2^kじゃないので、aはsquaresからNより小さい最大のものを選ぶ
    int a = 0;
    for(auto eachs : squares){
      if (eachs > a && eachs < N){
        a = eachs;
      }
    }
    int b = 1 ^ N ^ a;

    oi(N); oi(a); br();
    oi(b); oi(N*2); br();
  }



// -- main() end -- //
}

