		if(val&1)ans.emplace_back(mp(val+n,n));
		else ans.emplace_back(mp(val,n));
		if(ls<=2)ans.emplace_back(mp(3,n+n));
		else ans.emplace_back(mp(ls+n,n+n));
	}
	for(auto p:ans)pr1(p.first),pr2(p.second);
	return 0;
}

