    cout << pii(n+i, n+i+1) << '\n';
  }
  cout << pii(last, n+1) << '\n';

  switch (n & 3) {
    case 0:
      cout << pii(n, 1 << (31 - __builtin_clz(n))) << '\n';
      cout << pii(2*n, n - (1 << (31 - __builtin_clz(n))) + 1) << '\n';
      return;
    case 1:
      cout << pii(n-1, n) << '\n' << pii(1, n) << '\n';
      cout << pii(2*n-1, 2*n) << '\n' << pii(1, 2*n-1) << '\n';
      return;
    case 2:
      cout << pii(n-2, n-1) << '\n' << pii(1, n-1) << '\n';
      cout << pii(2*n-2, 2*n-1) << '\n' << pii(1, 2*n-2) << '\n';
      cout << pii(n-1, n) << '\n' << pii(2, 2*n) << '\n';
      return;
  }
