            ret.pb(P(te + 1, te + 2));
            ret.pb(P(te + 2, te + 3));
            ret.pb(P(te + 2, 1));
            ret.pb(P(te + 1 + n, 1));
            ret.pb(P(te + 1 + n, te + 2 + n));
            ret.pb(P(te + 1 + n, te + 3 + n));

        } else if (b == 2) {
            // はさむ
            rep1(i, len - 1) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
            ret.pb(P(te + len, 1));
            ret.pb(P(1, te + 1 + n));
        } else if (b == 0) {
            // そのままくっつける
            rep1(i, len - 1) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
            ret.pb(P(te + len, te + 1 + n));
            ret.pb(P(te + len + n, 1));
        } else if (b == 1) {
            // むりやり
            rep1(i, len - 2) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
            ret.pb(P(te + len - 1, te + 1 + n));
            int a = (te + 1) ^ n;
            ret.pb(P(n, a));
            ret.pb(P(a, te + 1));
            ret.pb(P(te + 1, 2 * n));
        } else if (b == 3) {
            rep1(i, len - 4) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
