using pi = pair<int, int>;
const int mod = 1e9 + 7;
const int MAXN = 200005;

struct disj{
	int pa[MAXN];
	void init(int n){
		iota(pa, pa + n + 1, 0);
	}
	int find(int x){
		return pa[x] = (pa[x] == x ? x : find(pa[x]));
	}
	bool uni(int p, int q){
		p = find(p); q = find(q);
		if(p == q)return 0;
		pa[q] = p; return 1;
	}
}disj;

int n;
vector<int> gph[MAXN];
vector<pi> edg;
int par[18][MAXN], prec[MAXN], dep[MAXN];

int lca(int s, int e){
	if(dep[s] > dep[e]) swap(s, e);
	int dx = dep[e] - dep[s];
	for(int i=0; i<18; i++){
		if((dx >> i) & 1) e = par[i][e];
	}
	for(int i=17; i>=0; i--){
		if(par[i][s] != par[i][e]){
			s = par[i][s];
			e = par[i][e];
		}
	}
	if(s != e) return par[0][s];
	return s;
}

void dfs(int x, int p){
	for(auto &i : gph[x]){
		if(i != p){
			dep[i] = dep[x] + 1;
			par[0][i] = x;
			prec[i] = prec[x] ^ (i > n ? (i-n) : i);
			dfs(i, x);
		}
	}
}
void add_edge(int s, int e){
	assert(1 <= s && s <= 2 * n);
	assert(1 <= e && e <= 2 * n);
	assert(disj.uni(s, e));
	edg.emplace_back(s, e);
	gph[s].push_back(e);
	gph[e].push_back(s);
}

int main(){
