	if((n & -n) == n){
		puts("No");
		return 0;
	}
	if(n == 3){
		puts("Yes");
		for(int i=2; i<=n+n; i++) printf("%d %d\n", i-1, i);
		return 0;
	}
	disj.init(n + n);
	int N = (n - 1) / 4;
	for(int i=1; i<=4*N-1; i++){
		if(i != 4 * N - 1){
			add_edge(i, i + 1);
			add_edge(i + n, i + n + 1);
		}
		else{
			add_edge(4 * N - 1, n + 1);
		}
