        if ((i & (3ll)) == 0) {
            if (i == n) {
                for (ll j = 30; j >= 0; j--) {
                    if ((i & (1ll << j))) {
                        ll snd = (i ^ (1ll << j));
                        ans.push_back({(1ll << j), i});
                        ans.push_back({i, snd});
                        j = -1;
                    }
                }
            } else {
                ans.push_back({i, 1 + n});
                ans.push_back({i + 1, 1 + n});
                ans.push_back({i + n, i + 1});
                ans.push_back({i, i + n + 1});
                i++;
            }
            continue;
        }
        ll cnct = (i - (i & 3ll));
        if ((i & 3ll) == 2ll) {
            ans.push_back({i, cnct});
            ans.push_back({i + n, 3});
        } else {
            ans.push_back({i, cnct});
            ans.push_back({i + n, 2 + n});
        }
    }

    cout << "Yes\n";
    for (auto cur : ans) {
        cout << cur.first << " " << cur.second;
        cout << "\n";
    }

    return 0;
}

