            if(i==3)o(i-2,i+1);
            else{
                ll t=1;
                for(;;){
                    t*=2;
                    if(t>i+1){
                        o(i-2,i+1);
                        break;
                    }
                    if(i+1==t){
                        if((n&t)==t){
                            o(t,las);
                            las=t;
                        }
                        else{
                            o(i-2,i+1);

                        }
                        break;
                    }
                }
            }
        }
    }
    if(n%4==1){
        o(n,n-1);
        o(1+n,n+n);
        o(n+n,n-1+n);
    }
    if(n%4==2){
        o(n-1,n-2);

        o(1+n,n+n-1);
        o(n+n-1,n-2+n);
        o(n,n-2);
        o(3,n+n);
    }
    if(n%4==0){
        ll u=1;
        ll uu=1;
        for(;;){
            u*=2;
            if(u>n){
                u/=2;
                break;
            }
        }
        for(;;){
            uu*=2;
            if((n&uu)==uu){
                break;
            }
        }
        o(n,u);
        o(n+n,uu);
    }
}

