int main() {
    int n;
    scanf("%d", &n);

    int te = 1;
    while (1) {
        if (te - 1 > n) {
            break;
        } else {
            te *= 2;
        }
    }
    te /= 2;
    te--;

    int len = n - te;
    int b = len % 4;

    // 判定
    if (n <= 2 || b == 3 || len == 1) {
        printf("No\n");
        return 0;
    }

    // 基本
    rep1(i, te - 1) {
        ret.pb(P(i, i + 1));
        ret.pb(P(i + n, i + n + 1));
    }
    ret.pb(P(te, n + 1));

    if (len > 0) {
        if (b == 2) {
            // はさむ
            rep1(i, len - 1) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
            ret.pb(P(te + len, 1));
            ret.pb(P(1, te + 1 + n));
        } else if (b == 0) {
            // そのままくっつける
            rep1(i, len - 1) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
            ret.pb(P(te + len, te + 1 + n));
            ret.pb(P(te + len + n, 1));
        } else if (b == 1) {
            // むりやり
            rep1(i, len - 2) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
            ret.pb(P(te + len - 1, te + 1 + n));
            int a = (te + 1) ^ n;
            ret.pb(P(n, a));
            ret.pb(P(a, te + 1));
            ret.pb(P(te + 1, 2 * n));
        }
    }

    printf("Yes\n");
    rep(i, ret.size()) {
        printf("%d %d\n", ret[i].fr, ret[i].sc);
    }

    /* --------------------------------- */
    return 0;
}

