int main(void){

	int n; scanf("%d", &n);
	edges = std::vector<std::vector<int>>(2*n+1);

	int t2=1;
	while(t2<=n) t2 *= 2;
	if(t2==n){ // Impossible
		printf("No\n");
		return 0;
	}
	else if(n%2 == 1){
		for(int i=2; i<=n; i+=2){ // 2-3-1-2-3, 4-5-1-4-5, 6-7-1-6-7, ...
			newedge(i, i+1);
			newedge(i+1, 1);
			newedge(1, i+n);
			newedge(i+n, i+1+n);
		}
		newedge(n+1, 2);
	}
	else{

		for(int i=2; i<n; i+=2){ // 2-3-1-2-3, 4-5-1-4-5, 6-7-1-6-7, ...
			newedge(i, i+1);
			newedge(i+1, 1);
			newedge(1, i+n);
			newedge(i+n, i+1+n);
		}
		newedge(n+1, 2);

		for(int x=2; x<n; x++){
			if((n^x) < n && (n^x) != x){

				newedge(n+n, x+n);
				newedge((n^x), n);
				break;
			}
		}
	}

	printf("Yes\n");
	for(int i=1; i<=2*n; i++)
		for(auto e: edges[i]) 
			if(i<e) printf("%d %d\n", i, e);
	return 0;
}

