int n;

int main(){
	scanf("%d", &n);
	bool valid = true;
	for(int i = 0; (1<<i) <= n; ++i){
		if((1<<i) == n)
			valid = false;
	}
	if(valid){
		// Make 1 as root, and all consecutive odd-even number as branches
		// General path	: 2i - 2i+1 - 1 - 2i - 2i+1
		// Last path
		//		Odd 	: n - (n-1) - 1 - n - (n-1)
		//		Even 	: (n-1) - (n-2) - 1 - (n-1) - (n-2)
		printf("Yes\n");
		for(int i = 2; i < n; i += 2){
			if(n%2 == 0)
				assert(i != n && i+1 != n);
			printf("%d %d\n", i, i+1);
			printf("%d %d\n", i+1, 1);
			printf("%d %d\n", 1, n+i);
			printf("%d %d\n", n+i, n+i+1);
		}
		// Special path for (1, n+1): (n+1) - 2 - 3 - 1
		printf("%d %d\n", n+1, 2);
		if(n%2 == 0){
			// Special path for (n, 2*n): n - (n-1) - 1 - 3 - 2 - (n+1) - (2*n)
			printf("%d %d\n", n, n-1);
			printf("%d %d\n", n+1, 2*n);
		}
	}else{
		printf("No\n");
	}
}

