		for(int i = 1; i < t - 1; ++i) {
			cout << i + n << ' ' << i + n + 1 << '\n';
		}

		for(int i = t; i < n; ++i) {
			cout << i << ' ' << i + 1 << '\n';
		}

		if(Xor != 0) {
			cout << n << ' ' << Xor << '\n';
			cout << Xor << ' ' << t + n << '\n';
		}

		for(int i = t; i < n; ++i) {
			cout << i + n << ' ' << i + n + 1 << '\n';
		}
	} else {
		if(cnt == 1) {
			cout << "No" << '\n';
		} else {
			cout << "Yes" << '\n';
