			}
			cout << node.back() << ' ' << 1 << '\n';
			cout << 1 << ' ' << node[0] + n << '\n';
			for(int i = 0; i + 1 < node.size(); ++i) {
				cout << node[i] + n << ' ' << node[i + 1] + n << '\n';
			}

			int v = n ^ t;
			vector<int> a;
			a.emplace_back(1);
			a.emplace_back(v);
