int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N;
  cin >> N;
  if (!(N & (N-1))) { // N=2^n
    cout << "No" << endl;
    return 0;
  }
  stringstream ss;
  set_edge(ss, 1,2);
  set_edge(ss, 2,3);
  set_edge(ss, 3,1+N);
  set_edge(ss, 1+N,2+N);
  set_edge(ss, 2+N,3+N);
  int c = (N-3);
  if (N % 2 == 0) {
    c--;
  }
  for (int i = 0; i < c; i+=2) {
    set_edge(ss, i+4+N, 1+N);
    set_edge(ss, i+5+N, i+4+N);
    set_edge(ss, i+5, 1+N);
    set_edge(ss, i+4, i+5);
  }
  if (N%2==0) {
    // N, 2Nを入れる必要がある.
    int p = N ^ (N-1) ^ 1; // p1 < N-1
    set_edge(ss, N, N-1);
    if (p & 1) { // odd
      set_edge(ss, N*2, p);
    } else {
      set_edge(ss, N*2, p+N);
    }
  }
  cout << "Yes" << endl;
  cout << ss.str() << endl;
  return 0;
}

