int main(int argc, char *argv[]) {
  // read inputs
  int N;
  scanf("%d", &N);

  // impossible if N <= 2
  if (N <= 2) {
    printf("No\n");
    return 0;
  }

  // possible if N >= 3
  vector<int> as, bs;
  as.push_back(1);
  bs.push_back(2);
  as.push_back(2);
  bs.push_back(3);
  as.push_back(N + 1);
  bs.push_back(N + 2);
  as.push_back(N + 2);
  bs.push_back(N + 3);
  as.push_back(3);
  bs.push_back(N + 1);
  for (int i = 4; i <= N; i++) {
    as.push_back(i);
    bs.push_back(N + i - 2);
    as.push_back(i);
    bs.push_back(i - 1);
  }

  // print answer
  assert(as.size() == 2 * N - 1);
  for (int i = 0; i < 2 * N - 1; i++) {
    printf("%d %d\n", as[i], bs[i]);
  }

  return 0;
}

