int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  if (__builtin_popcount(n) == 1) {
    cout << "No" << '\n';
    return 0;
  }
  cout << "Yes" << '\n';
  vector<int> all(n);
  iota(all.begin(), all.end(), 1);
  int v = 0;
  for (int x : all) {
    v ^= x;
  }
  if (v == 0) {
    for (int i = 1; i < 2 * n; i++) {
      cout << i << " " << i + 1 << '\n';
    }
    return 0;
  }
  if (v <= n) {
    all.erase(all.begin() + v - 1);
    while (true) {
      shuffle(all.begin(), all.end(), rng);
      vector<int> pref(1, 0);
      for (int rot = 0; rot < 2; rot++) {
        for (int i = 0; i < n - 1; i++) {
          pref.push_back(pref.back() ^ all[i]);
        }
      }
      map<int, int> mp;
      int from = -1, to = -1;
      for (int it = 0; it < (int) pref.size(); it++) {
        int x = pref[it];
        if (mp.find(x ^ v) != mp.end()) {
          from = mp[x ^ v];
          to = it;
          break;
        }
        mp[x] = it;
      }
      if (from != -1) {
        vector<int> vers;
        for (int i = 0; i < n - 1; i++) {
          vers.push_back(all[i]);
        }
        for (int i = 0; i < n - 1; i++) {
          vers.push_back(all[i] + n);
        }
        for (int i = 0; i < 2 * n - 3; i++) {
          cout << vers[i] << " " << vers[i + 1] << '\n';
        }
        cout << vers[from] << " " << v << '\n';
        cout << vers[to - 1] << " " << v + n << '\n';
        break;
      }
    }
    return 0;
  }
  assert(v == n + 1);
  vector<int> vers;
  for (int i = 2; i <= n - 1; i++) {
    vers.push_back(i);
  }
  swap(vers[vers.size() - 2], vers[vers.size() - 1]);
  for (int i = 2; i <= n - 1; i++) {
    vers.push_back(i + n);
  }
  swap(vers[vers.size() - 2], vers[vers.size() - 1]);
  for (int i = 0; i < (int) vers.size() - 1; i++) {
    cout << vers[i] << " " << vers[i + 1] << '\n';
  }
  cout << n - 1 << " " << 1 << '\n';
  cout << n - 2 << " " << n + 1 << '\n';
  cout << n - 2 << " " << n << '\n';
  cout << n + 2 << " " << n + n << '\n';
  return 0;
}

