int is_pow2(int N) {
    while (N%2 == 0) N/=2;
    if(N==1) return true;
    return false;
}

int get_r(int N){
    int r = 1;
    while (N%(2*r) == 0) r*=2;
    return r;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    cin >> N;

    if (is_pow2(N)) {
        cout << "No" << endl;
        return 0;
    }

    cout << "Yes" << endl;

    int K = (N-1) / 2;
    for(int i=1;i<=K;i++) {
        cout << 1 << " " << 2*i << endl;
        cout << 2*i << " " << 2*i + 1 << endl;
        cout << 1 << " " << N + 2*i + 1 << endl;
        cout << N + 2*i + 1 << " " << N + 2*i << endl;
    }

    cout << N+1 << " " << 3 << endl;

    if (N % 2 == 0) {
        int r = get_r(N);
        int s = N - r;
        cout << N << " " << r << endl;
        cout << N + N << " " << N + s + 1 << endl;
    }

    return 0;
}

