int N;
vector<pair<int,int>> E;
vector<int> EE[101010];
map<int,int> M;

void add(int x,int y) {
	E.push_back({x,y});
	EE[x].push_back(y);
	EE[y].push_back(x);
}

void dfs(int cur,int pre,int v) {
	if(cur>N) v^=(cur-N);
	else v^=cur;
	M[v]=cur;
	FORR(e,EE[cur]) if(e!=pre) dfs(e,cur,v);
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;
	if((N&(N-1))==0) return _P("No\n");

	x=1;
	while(x*2<=N) x*=2;

	cout<<"Yes"<<endl;
	if(N+1==x*2) {
		for(i=1;i<x;i++) {
			add(i,i+x);
			add(i+x,x);
			add(x,i+N);
			add(i+N,i+x+N);
		}
		add(1,x+N);
	}
	else {
		y=x/2;
		for(i=1;i<y;i++) {
			add(i,i+y);
			add(i+y,y);
			add(y,i+N);
			add(i+N,i+y+N);
		}
		add(1,y+N);
		add(x,x+1);
		add(x+1,1);
		add(1,x+N);
		add(x+N,x+1+N);

		dfs(x+N,-1,0);

		for(i=x+2;i<=N;i++) {
			add(i,x+N);
			assert(M.count(i));
			add(i+N,M[i]);
		}

	}

	FORR(e,E) cout<<e.first<<" "<<e.second<<endl;
}


