        id[cnt] = x;
        par[x] = p;
        depth.push_back(d);
        disv[x] = dis;
        in[x] = cnt++;
        forg(gi, g[x]) {
            if (t == p) { continue; }
            dfs(t, x, d + 1, dis + c);
            id[cnt] = x;
            depth.push_back(d);
            cnt++;
        }
    }
    void precalc() {
        never = false;
        cnt = 0;
        depth.clear();
        disv.assign(n, 0);
        in.assign(n, -1);
        id.assign(2 * n - 1, -1);
        par.assign(n, -1);
        dfs(root, -1, 0);
        rmq.init(depth);
    }
public:
    using undigraph<T>::g;    using undigraph<T>::n;    using undigraph<T>::edges;    using undigraph<T>::usedv;
    vector<int> disv;
    vector<signed> depth, par;
    int root;
    tree(int n_, int root = 0) : undigraph<T>(n_), root(root) { n = n_; }

    int lca(int a, int b) {
        if (never)precalc();
        int x = in[a];
        int y = in[b];
        if (x > y) { swap(x, y); }
        int pos = rmq.query(x, y + 1);
        return id[pos];
    }
    int dis(int a, int b) {
        if (never)precalc();
        int x = in[a];
        int y = in[b];
        if (x > y) { swap(x, y); }
        int pos = rmq.query(x, y + 1);
        int p = id[pos];
        return disv[a] + disv[b] - disv[p] * 2;
    }
    //O(N) 頂点に対しての処理を渡す
    void for_each_(int u, int v, function<void(int)> fnode) {
        int r = lca(u, v);
        while (u != r) {
            fnode(u);
            u = par[u];
        }
        while (v != r) {
            fnode(v);
            v = par[v];
        }
        fnode(r);
    }
