vector<tree<int>> trees(int k) {    int siz = pow(k, k - 2);    vi mas(siz);/*どの辺を使うかbitで持つ*/    str name = "C:\\Users\\kaout\\Desktop\\trees_sizek\\tree_size";    name += tos(k) + ".txt";    if (k == 6) name = "C:\\Users\\kaout\\Desktop\\trees_sizek\\nazeka6.txt";    ifstream ina(name);    rep(i, siz) ina >> mas[i];    vp edges;    rep(i, k)rep(j, i + 1, k)edges.eb(i, j);    vector<tree<>> res;    int ind = 0;    fora(m, mas) {        int tm = m;        tree<> g(k);        while (tm) {            int lb = lbit(tm);            int id = log2(lb);            g.add(edges[id].first, edges[id].second);            tm ^= lb;        }        res.push_back(g);    }    return res;}
//頂点数がkの木を一つ返す サイズが0の木が帰ったら終了
tree<int> next_tree(int k) {    static str name;    static ifstream ina;    static int rem;    static vp edges;    static int pk = -1;/*前回見たk*/    if (pk != k) {        if (~pk)ina.close();        edges.clear();        pk = k;        name = (k == 6) ? "C:\\Users\\kaout\\Desktop\\trees_sizek\\nazeka6.txt" : "C:\\Users\\kaout\\Desktop\\trees_sizek\\tree_size" + tos(k) + ".txt";        ina = ifstream(name);        rem = pow(k, k - 2);/*Cayleyの定理*/        rep(i, k)rep(j, i + 1, k)edges .emplace_back(i, j);        pk =  k;    }    tree<int> g(k);    if (rem == 0) {        g.resize(0);        return g;    }    int m;    ina >> m;    while (m) {        int lb = lbit(m);        int id = log2(lb);        g.add(edges[id].first, edges[id].second);        m ^= lb;    }    rem--;    return g;}
