			edge(n + 2, 1);
			edge(1, n + 1 + N);
			edge(n + 1 + N, n + 2 + N);
		}
		else if(N % 4 == 2) {
			cout << "Yes\n";
			int n = N - 3;

			vector<int> vec;

			rep(i, 1, n + 1) vec.pb(i);
			rep(i, 1, n + 1) vec.pb(i + N);
			rep(i, 0, sz(vec) - 1) edge(vec[i], vec[i + 1]);
			edge(n + 1, n + 2);
			edge(n + 2, n + 3);
			edge(n + 3, 3);
			edge(3, n + 1 + N);
			edge(n + 1 + N, n + 2 + N);
			edge(n + 2 + N, n + 3 + N);
		}
		else {
			if(__builtin_popcount(N) == 1) {
				cout << "No\n";
