				int b = N ^ a;
				vec.pb(a);
				vec.pb(b);
				for(int i = 1; i <= N - 1; i++) {
					if(i != a && i != b) vec.pb(i);
				}
				vec.pb(a + N);
				vec.pb(b + N);
				for(int i = 1; i <= N - 1; i++) {
					if(i != a && i != b) vec.pb(i + N);
				}
				rep(i, 0, sz(vec) - 1) edge(vec[i], vec[i + 1]);
				edge(N, a);
				edge(b, N + N);
			}
		}
	}
}

