}

Matrix Pow(Matrix matrix, ll x) {
    Matrix res = vector<vector<ll>>(matrix.size(), vector<ll>(matrix.size(), 0));
    for (int i = 0; i < (int)matrix.size(); i++) {
        res[i][i] = 1;
    }
    while (x) {
        if (x & 1) {
            res = res * matrix;
        }
        matrix = matrix * matrix;
        x >>= 1;
    }
    return res;
}


