const int N = 1e5 + 5;

struct DSU {
  int parent[N];
  void init() {
    for (int i = 0; i < N; ++i) {
      parent[i] = i;
    }
  }
  int getRoot(int x) {
    if (parent[x] == x) return x;
    return parent[x] = getRoot(parent[x]);
  }
  void join(int x, int y) {
    x = getRoot(x);
    y = getRoot(y);
    parent[x] = y;
  }
} dsu;

struct Edge {
  int from, to;
  bool out_to = false;
};

vector<Edge> edges;
vector<int> mst_adj[N];
bool deg[N];

void kruskal() {
  dsu.init();
  for (int i = 0; i < edges.size(); ++i) {
    auto& edge = edges[i];
    if (dsu.getRoot(edge.from) == dsu.getRoot(edge.to)) {
      edge.out_to = false;
      deg[edge.from] ^= 1;
    } else {
      dsu.join(edge.from, edge.to);
      mst_adj[edge.from].emplace_back(i);
      mst_adj[edge.to].emplace_back(i);
    }
  }
}

void dfs(int node, int parent, int p_edge) {
  for (int v : mst_adj[node]) {
    auto& edge = edges[v];
    int to = edge.from ^ edge.to ^ node;
    if (to == parent) continue;
    dfs(to, node, v);
  }
  if (deg[node]) {
    if (p_edge == -1) {
      cout << -1 << endl;
      exit(0);
    }
    auto& edge = edges[p_edge];
    if (node == edge.to) {
      edge.out_to = true;
    }
    deg[node] ^= 1;
  } else {
    if (p_edge == -1) return;
    auto& edge = edges[p_edge];
    if (node != edge.to) {
      edge.out_to = true;
    }
    deg[parent] ^= 1;
  }
}

