    return;
  }
  vector<P> v;
  for (ll i = 2; i+1 <= n; i += 2) v.eb(i, i+1);
  if (n % 2 == 1) {
    ans = make_graph(n, v);
  }
  else {
    ll x = n & -n, y = n ^ x;
