namespace _buff {

const size_t BUFF = 1 << 19;
char ibuf[BUFF], *ib = ibuf, *ie = ibuf;
char getc() {
    if (ib == ie) {
        ib = ibuf;
        ie = ibuf + fread(ibuf, 1, BUFF, stdin);
    }
    return ib == ie ? -1 : *ib++;
}

}

LL read() {
    using namespace _buff;
    LL ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

int main() {
    int n = read();
    if (__builtin_popcount(n) == 1) {
        return puts("No"), 0;
    }

    vector<pair<int, int> > ans;
    ans.emplace_back(1, 2);
    ans.emplace_back(2, 3);
    ans.emplace_back(1, 3 + n);
    ans.emplace_back(3 + n, 2 + n);
    ans.emplace_back(2 + n, 1 + n);

    for (int i = 4; i <= n - ((n & 1) ^ 1); ++i) {
        if (i & 1) {
            ans.emplace_back(1, i + n);
            ans.emplace_back(i - 1, i);
        } else {
            ans.emplace_back(1, i);
            ans.emplace_back(i + n + 1, i + n);
        }
    }

    if (!(n & 1)) {
        for (int a = 2; a < n; ++a) {
            int b = n ^ 1 ^ a;
            if (1 < b && b < n) {
                ans.emplace_back(a & 1 ? a + n : a, n);
                ans.emplace_back(b & 1 ? b + n : b, n << 1);
                break;
            }
        }
    }

    puts("Yes");
    for (auto &pr : ans) {
        printf("%d %d\n", pr.first, pr.second);
    }
    return 0;
}

