        cout<<NO<<endl;
        return;
    }
    cout<<YES<<endl;
    cout<<1<<" "<<2<<endl;
    cout<<2<<" "<<3<<endl;
    cout<<3<<" "<<N+1<<endl;
    cout<<N+1<<" "<<N+2<<endl;
    cout<<N+2<<" "<<N+3<<endl;
    for(int i=4;i+1<=N;i+=2){
        cout<<i<<" "<<i+1<<endl;
        cout<<i+1<<" "<<1<<endl;
        cout<<1<<" "<<N+i<<endl;
        cout<<N+i<<" "<<N+i+1<<endl;
    }
    if(N%2==0){
        long long k=1;
        while((k|N) != N){
            k*=2;
        }
        cout<<N<<" "<<k*2 - 1<<endl;
        cout<<k*2 - 1<<" "<<2*N<<endl;
    }
    return;
}

