		cout << "No\n";
		return;
	}

	int xd = n;
	while (xd % 4 != 3) xd--;

	vector<int> a;
	for (int i = 1; i <= xd; i++) a.push_back(i);
	for (int i = 1; i <= xd; i++) a.push_back(i);

	stringstream ss;
	ss << "Yes\n";
	for (int i = 1; i < xd; i++) {
		ss << i << ' ' << i+1 << '\n';
	}
	ss << xd << ' ' << n+1 << '\n';
	for (int i = n+1; i < xd + n; i++) {
		ss << i << ' ' << i+1 << '\n';
	}
	for (int j = xd + 1; j <= n; j++) {
		map<int, int> pr;
		int xrcur = 0;
		int f = 0;
		for (int i = 0; i < a.size(); i++) {
			xrcur ^= a[i];
			// we need to find pr[ind] = j ^ xrcur

			if (pr.find(j ^ xrcur) != pr.end()) {
				// ind and i
				ss << pr[j ^ xrcur]+1 << ' ' << j << '\n';
				ss << j+n << ' ' << i+1 << '\n';
				f = 1;
				break;
			}

			pr[xrcur] = i;
		}

		if (!f) {
			cout << "No"; return;
		} 
	}

	cout << ss.str();
}

