vector<pii> getOdd(int k, int n){
	// 2 * k + 1
	vector<pii> ret;
	for(int i = 1; i <= k; i++){
		ret.push_back({1, 2 * i});
		ret.push_back({1, 2 * i + 1});
		ret.push_back({2 * i, n + 2 * i + 1});
		ret.push_back({2 * i + 1, n + 2 * i});
	}
	ret.push_back({n + 2, n + 1});
	return ret;
}

