void solve(int N){
  if(popcount(N) == 1){
    cout << "No" << endl;
    return;
  }

  vector<pair<int,int>> ans;

  FOR(i,1,(N+1)/2){
    int j = i*2;
    int k = j+1;

    ans.push_back({j+N,k});
    ans.push_back({k,1});
    ans.push_back({1,j});
    ans.push_back({j,k+N});
  }

  ans.push_back({1+N,2});

  if(N%2==0){
    FORE(i,2,N-1){
      int j = (N+1)^i;
      if(i!=j and j<=N-1){
        ans.push_back({N,i});
        ans.push_back({2*N,j});
        break;
      }
    }
  }

  cout << "Yes" << endl;
  for(auto &p : ans){
    cout << p.fst << " " << p.snd << endl;
  }
  return;
}

