                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
            }
            ret.pb(P(te + len, 1));
            ret.pb(P(1, te + 1 + n));
        } else if (b == 0) {
            // そのままくっつける
            rep1(i, len - 1) {
                ret.pb(P(te + i, te + i + 1));
                ret.pb(P(te + i + n, te + i + 1 + n));
