void _main()
{
    ll n; llin(n);

    rep (i, 63) {
        if (n == (1LL<<i)) {
            cout << "No" <<endl;
            return;
        }
    }

    ll base = -1LL;
    rep (i, 63) {
        ll val = (1LL<<i) - 1LL;
        if (n < val) break;
        base = val;
    }

    S V<t2> anslist;
    srep (v, 1, base) {
        anslist.pb(t2(v, v+1LL));
        anslist.pb(t2(v+BORDER, v+1LL+BORDER));
    }
    anslist.pb(t2(base, 1LL + BORDER));

    if (n & 1LL) {
        srep (v, base+1LL, n+1LL) {
            if (v & 1LL) continue;
            anslist.pb(t2(1LL, v));
            anslist.pb(t2(v, v+1LL));
            anslist.pb(t2(1LL, v+1LL+BORDER));
            anslist.pb(t2(v+1LL+BORDER, v+BORDER));
        }
    }
    else {
        ll center = n - (base + 1LL);
        assert(!(center & 1LL));
        srep (v, base+1LL, n) {
            if (v & 1LL) continue;
            anslist.pb(t2(center, v));
            anslist.pb(t2(v, v+1LL));
            anslist.pb(t2(center+1LL, v+1LL+BORDER));
            anslist.pb(t2(v+1LL+BORDER, v+BORDER));
        }
        anslist.pb(t2(n, base+1LL));
        anslist.pb(t2(n+BORDER, center));
    }

    for (auto ans : anslist) {
        ll v1 = get<0>(ans);
        ll v2 = get<1>(ans);
        if (v1 >= BORDER) v1 = (v1 % BORDER) + n;
        if (v2 >= BORDER) v2 = (v2 % BORDER) + n;
        printf("%lld %lld\n", v1, v2);
    }
}

