		// build chain of 1 to 3
		ans.push_back({ 1, 2 });
		ans.push_back({ 2, 3 });
		ans.push_back({ 3, n + 1 });
		ans.push_back({ n + 1, n + 2 });
		ans.push_back({ n + 2, n + 3 });

		for (i = 4; i < n; i += 2) {
			ans.push_back({ i, n + 1 });
			ans.push_back({ i, i + 1 });
			ans.push_back({ n + i + 1, n + 1 });
			ans.push_back({ n + i, n + i + 1 });
		}

		if (n % 2 == 0) {
			// find the last 1-bit of n
			x = 1;
			while (!(x & n)) x *= 2;

			ans.push_back({ x + 1 + n, n });
			ans.push_back({ (n - x), n });
		}

		cout << "Yes\n";
		for (auto p : ans) cout << p.first << " " << p.second << "\n";
	}



	return 0;
}

