const int N = 1e5 + 5;

int n;

void O(int x, int y) {
	printf("%d %d\n", x, y);
}

int main() {
	scanf("%d", &n);
	if (!(n - (n & (-n)))) {
		puts("No");
		return 0;
	}
	puts("Yes");
	if (n & 1) {
		O(1, 2);
		O(2, 3);
		O(3, 1 + n);
		O(1 + n, 2 + n);
		O(2 + n, 3 + n);
		for (int i = 4; i < n; i += 2) {
			int v = i ^ (i + 1);
			O(i, i + 1);
			O(i + 1, v);
			O(v, i + n);
			O(i + n, i + n + 1);
		}
	} else {
		int x = (n & (-n)) - 1;
		int y = x + 1;
		assert(!(x ^ y ^ (n - 1) ^ n));
		O(y, x);
		O(x, n - 1);
		O(n - 1, n);
		O(n, y + n);
		O(y + n, x + n);
		O(x + n, n + n - 1);
		O(n + n - 1, n + n);
		int hig = 1;
		while ((hig << 1) < n)
			hig <<= 1;
		vector<int> a;
		for (int i = 1; i < hig; i++) {
			a.push_back(i);
		}
		a.erase(find(a.begin(), a.end(), x));
		a.erase(find(a.begin(), a.end(), y));
		for (int i = 1; i < (signed) a.size(); i++)
			O(a[i - 1], a[i]);
		O(a.back(), x);
		O(y, a[0] + n);
		for (int i = 1; i < (signed) a.size(); i++)
			O(a[i - 1] + n, a[i] + n);

		a.clear();
		int z = x ^ (n - 1);
		O(z, x);
		O(n - 1, z + n);
		for (int i = hig; i < n - 1; i++)
			a.push_back(i);
		a.erase(find(a.begin(), a.end(), z));
		assert(!(a.size() & 1));
		for (int i = 1; i < (signed) a.size(); i += 2) {
			int v = a[i - 1] ^ a[i];
			O(a[i - 1], a[i]);
			O(a[i], v);
			O(v, a[i - 1] + n);
			O(a[i - 1] + n, a[i] + n);
		}
	}
	return 0;
}

