class Solve {
public:

    void solve() {
        int N;
        cin >> N;
        if (N <= 2 || N == 4) {
            cout << "No" << endl;
            return;
        }

        int bsize = (N + 1) / 4 * 4 - 1;
        vector<int> base;
        for (int i = 0; i + 3 <= bsize; i += 4) {
            for (int j = 0; j < 4; ++j) {
                if (i + j > 0)
                    base.push_back(i + j);
            }
            for (int j = 0; j < 4; ++j) {
                if (i + j > 0)
                    base.push_back(i + j + N);
            }
        }
        if (N % 4 != 0) {
            for (int i = 0; i < 6; ++i) {
                base.push_back(*base.begin());
                base.erase(base.begin());
            }
        } else {
            for (int val = 7; val >= 4; --val) {
                auto pt = find(all(base), val);
                base.erase(pt);
                base.push_back(val);
            }
            for (int val = 7 + N; val >= 4 + N; --val) {
                auto pt = find(all(base), val);
                base.erase(pt);
                base.push_back(val);
            }
        }

        vector<pair<int, int>> edges;
        for (int i = 0; i + 1 < base.size(); ++i) {
            edges.emplace_back(base[i], base[i + 1]);
        }

        int k = N / 4;

        if (N % 4 == 0) {
            if (__builtin_popcount(N) == 1) {
                cout << "No" << endl;
                return;
            }

            edges.emplace_back(2 * N - 1, 2 * N);
            edges.emplace_back(7, N);
        } else if (N % 4 != 3) {
            edges.emplace_back(1, 4 * k + 1);
            edges.emplace_back(4 * k + 1, 4 * k);
            edges.emplace_back(1, 4 * k + N);
            edges.emplace_back(4 * k + N, 4 * k + 1 + N);

            if (N % 4 == 2) {
                edges.emplace_back(2, 4 * k + 2);
                edges.emplace_back(4 * k + 1, 4 * k + 2 + N);
            }
        }

        cout << "Yes" << endl;
        for (auto edge : edges) {
            cout << edge.first << " " << edge.second << endl;
        }


    }

};


