const int   N   = 2e5 + 5;

typedef pair<int,int>   ii;

vector<int> g[N];
vector<ii>  E;

void addEdge(int u,int v)   {
    if (u > v)  swap(u,v);
    g[u].pb(v);
    g[v].pb(u);
    E.pb(ii(u,v));
}
void remEdge(int u,int v)   {
    if (u > v)  swap(u,v);

    if (find(all(E),ii(u,v)) != E.end())    {
        E.erase(find(all(E),ii(u,v)));
        g[u].erase(find(all(g[u]),v));
        g[v].erase(find(all(g[v]),u));
    }
}

