    for(int i = 0 ; i < s ; i += 4) {
        if (i)  {
            addEdge(i,i + 1);   i += n;
            addEdge(i,i + 1);   i -= n;

            addEdge(i + 3,i + n);
        }
        else
            addEdge(i + 3,n + 1);

        for(int j = 1 ; j < 3 ; ++j)    {
            addEdge(i + j,i + j + 1);   j += n;
            addEdge(i + j,i + j + 1);   j -= n;
        }
        addEdge(i + 3 + n,i + 4);
    }
    remEdge(s - 1 + n,s);

    if (n == s) {
