        int v = n ^ u;

        remEdge(u + n - 1,u);

        if (u + 4 < s)  {
            remEdge(u + n + 3,u + 4);
            addEdge(u + n - 1,u + 4);
        }
        addEdge(u,v);
        addEdge(u,n);
        addEdge(v,n + n);
    }
    if (n == s + 1) {
        addEdge(n,1);   addEdge(s + n,1);
        addEdge(s,n);   addEdge(n + n,s + n);
    }
    if (n == s + 2) {
        addEdge(n,1);
        addEdge(n,s + 1);
        addEdge(s,s + 1 + n);
        addEdge(s + 1 + n,2);
        addEdge(s + 1 + n,n + n);
