Scanner sc = Scanner(stdin);
Printer pr = Printer(stdout);

using P = pair<int, int>;

V<array<P, 2>> solve(int n) {
    V<array<P, 2>> res;
    if (n % 4 == 0 || n % 4 == 1) {
        res = solve(n - 2);
        int z = (n - 1) ^ n;
        // (n) - (n-1) - z - (n) - (n-1)
        res.push_back({{{n, 0}, {n - 1, 0}}});
        res.push_back({{{n - 1, 0}, {z, 0}}});
        res.push_back({{{z, 0}, {n, 1}}});
        res.push_back({{{n, 1}, {n - 1, 1}}});
        return res;
    }
    if (n % 4 == 2) {
        res = solve(n - 3);
        //           n
        //           |
        // (n-2) - (n-1) - 1 - (n-2) - (n-1)
        //                 |
        //                 2 - (n)
        res.push_back({{{n - 2, 0}, {n - 1, 0}}});
        res.push_back({{{n - 1, 0}, {1, 0}}});
        res.push_back({{{1, 0}, {n - 2, 1}}});
        res.push_back({{{n - 2, 1}, {n - 1, 1}}});

        res.push_back({{{n, 0}, {n - 1, 0}}});
        res.push_back({{{2, 0}, {n, 1}}});
        return res;
    }
    // naive
    V<P> path;
    for (int i = 0; i < n; i += 4) {
        for (int ph = 0; ph < 2; ph++) {
            for (int j = i; j < i + 4; j++) {
                if (j == 0) continue;
                path.push_back({j, ph});
            }
        }
    }
    int k = int(path.size());
    for (int i = 0; i < k - 1; i++) {
        res.push_back({{path[i], path[i + 1]}});
    }
    return res;
}

