VP solve(int n) {
    if (n <= 2) {
        return {};
    }

    int trials = 70;

    int m = 3;
    while (m + 4 <= n) {
        m += 4;
    }

    VI need;
    FOR(i,m+1,n) {
        need.pb(i);
    }

    while (trials--) {
        VI seq(m);
        FOR(i,0,m-1) {
            seq[i] = i + 1;
        }

        random_shuffle(seq.begin(), seq.end());

        VP res;

        if (!need.empty()) {
            map <int,int> prefXor;
            prefXor[0] = 0;

            res.resize(SIZE(need), {-1, -1});

            int pref = 0;
            FOR(i,0,m-1) {
                pref ^= seq[i];

                FOR(j,0,SIZE(need)-1) if (res[j].st == -1) {
                    int want = pref ^ need[j];
                    if (prefXor.count(want)) {
                        res[j] = {prefXor[want], i};
                    }
                }

                prefXor[pref] = i + 1;
            }
        }

        bool ok = true;
        for (auto &e : res) if (e.st == -1) {
            ok = false;
        }

        if (ok) {
            VP ans;

            FOR(i,0,m-2) {
                ans.pb({seq[i], seq[i+1]});
            }

            ans.pb({seq[m-1], seq[0] + n});

            FOR(i,0,m-2) {
                ans.pb({seq[i] + n, seq[i+1] + n});
            }

            FOR(j,0,SIZE(need)-1) {
                auto r = res[j];

                ans.pb({seq[r.st], need[j]});
                ans.pb({seq[r.nd], need[j] + n});
            }

            return ans;
        }
    }

    return {};
}

