		for(i=1;i<x;i++) {
			add(i,i+x);
			add(i+x,x);
			add(x,i+N);
			add(i+N,i+x+N);
		}
		add(1,x+N);
	}
	else {
		y=x/2;
		for(i=1;i<y;i++) {
			add(i,i+y);
			add(i+y,y);
			add(y,i+N);
			add(i+N,i+y+N);
		}
		add(1,y+N);
		add(x,x+1);
		add(x+1,1);
		add(1,x+N);
		add(x+N,x+1+N);

		dfs(x+N,-1,0);

