        cout << "No" << endl;
        return 0;
    }
    else {
        cout << "Yes" << endl;
    }
    vector<int> a, b;
    auto ae = [&](int x, int y) {
        a.push_back(x);
        b.push_back(y);
    };
    ae(1, 2);
    ae(3, 2);
    ae(3, N + 1);
    ae(N + 1, N + 2);
    ae(N + 3, N + 2);
    int s = 4;
    if (N % 2 == 0) {
        ae(4, 5);
