  cin >> N;

  // n == 2^x - 1 なら自明
  // n == 2^x なら不可能
  // 半開区間でXORが0になるようにする

  if (N % 2 == 0) {
    cout << "No" << endl;
    return 0;
  }
  else if (N == 1) {
    cout << "No" << endl;
    return 0;
  }

  int nplus1 = N+1;
  int bitCount = 0;
  while (nplus1 > 0) {
    nplus1 >>= 1;
    bitCount++;
  }
  int nx = 0;
  for (int i = 0; i < bitCount-1; i++) {
    nx <<= 1;
    nx = nx | 1;
  }
  vector<Pii> edge;
  for (int i = 1; i < nx; i++) {
    edge.push_back(Pii(i, i+1));
  }
  edge.push_back(Pii(nx, N+1));
  for (int i = 1; i < nx; i++) {
    edge.push_back(Pii(N+i, N+i+1));
  }
  for (int i = nx; i < N; i+=2) {
    edge.push_back(Pii(i+2, i+1));
    edge.push_back(Pii(i+1, 2));
    edge.push_back(Pii(3, N+i+2));
    edge.push_back(Pii(N+i+2, N+i+1));
  }

  cout << "Yes" << endl;
  for (auto x: edge) cout << x.first << " " << x.second << endl;
  return 0;
}
