  } else if (n == 3) {
    cout << "Yes" << endl;
    cout << "1 2" << endl;
    cout << "2 3" << endl;
    cout << "3 4" << endl;
    cout << "4 5" << endl;
    cout << "5 6" << endl;
    return 0;
