  p.resize(n * 2);
  for (int i = 0; i < k - 1; i++) {
    if (i < k - 2) {
      p[i].push_back(i + 1);
      p[i + n].push_back(i + n + 1);
    } else {
      p[i].push_back(n);
    }
  }

  p[k - 1].push_back(n);
  p[k].push_back(k - 1);
  p[k + n].push_back(0);
  p[k - 1 + n].push_back(k + n);
