  int sum = k;
  for (int i = n; i < k + n - 1; i++) {
    sum = sum ^ (i - n + 1);
    mp[sum] = i;
  }
  sum = (k ^ 1);
  for (int i = k - 2; i >= 0; i--) {
    sum = sum ^ (i + 1);
    mp[sum] = i;
  }
  for (int i = k + 1; i < n; i++) {
    p[i].push_back(k - 1);
    p[i + n].push_back(mp[i + 1]);
  }
