void addEdge(int a, int b) {
	ed.pb({a,b});
}

void dfs(int a, int b) {
	trav(t,adj[a]) if (t != b) {
		val[t] = val[a];
		if (t > N) val[t] ^= t-N;
		else val[t] ^= t;
		dfs(t,a);
	}
}

void solve() {
	ed.clear();
    int k = 1; while (2*k+1 <= N) k = 2*k+1;
    if (N == 1 || N == k+1) {
    	ps("No");
    	return;
    }
    vi seq = {1};
    int des = -1;
    if (N%2==0) {
    	des = N-k;
    	seq.pb(des);
    }
    FOR(i,2,k+1) if (i != des) seq.pb(i);
    int z = sz(seq); F0R(i,z) seq.pb(seq[i]+N);
    F0R(i,sz(seq)-1) addEdge(seq[i],seq[i+1]);
    for (int i = k+1; i+1 <= N; i += 2) {
    	addEdge(1,i); addEdge(i,i+1);
    	addEdge(1,i+1+N); addEdge(i+1+N,i+N);
    }
    if(N%2==0) {
    	addEdge(N,k+1);
    	addEdge(des,2*N);
    }
    ps("Yes"); assert(sz(ed) == 2*N-1);
    FOR(i,1,MX) adj[i].clear();
    trav(t,ed) {
    	ps(t.f,t.s);
    	adj[t.f].pb(t.s), adj[t.s].pb(t.f);
    }
    FOR(i,1,N+1) {
    	val[i] = i; dfs(i,0);
    	assert(val[N+i] == i);
    }
}

