    int N; cin >> N;
    V<int> pow2(N+1,0);
    for(int i = 1; i <= N+1; i *= 2) pow2[i] = 1;    
    corner(pow2[N],"No");

    V<int> flg(2*N+1,0);
    V<int> u,v;
    u.push_back(N+1); v.push_back(N+2);
    u.push_back(N+2); v.push_back(N+3);
    u.push_back(N+3); v.push_back(1);
    u.push_back(1); v.push_back(2);
    u.push_back(2); v.push_back(3);
