  while(rhs <= 2*n) {
    cout << last << " " << rhs << "\n";
    cout << rhs << " " << rhs-1 << "\n";
    cout << rhs-1 << " " << rhs-2 << "\n";
    cout << rhs-2 << " " << rhs-3 << "\n";
    last = rhs-3;
    rhs += 4;
  }
  if(n%2 == 1) {
    cout << n+3 << " " << 2*n << "\n";
    cout << 2*n << " " << 2*n-1 << "\n";
  }
  else {
    cout << n+3 << " " << 2*n-1 << "\n";
    cout << 2*n-1 << " " << 2*n-2 << "\n";
    cout << 2 << " " << 2*n << "\n";
    cout << (n-2) << " " << n << "\n";
  }
}

