	add((1 << k) - 1, n + 1);
	for (int i = 1; i + 1 < (1 << k); ++i)
		add(n + i, n + i + 1);
	for (int i = (1 << k); i <= n; i += 2) {
		if (i < n) {
			add(i, i + 1);
			add(1, i);
			add(n + i, n + i + 1);
			add(1, n + i + 1);
		}
		else {
			add(i, i - 1);
			int now = i ^ (i - 1);
			add(n + i, now - 1);
		}
	}
	return 0;
}

