char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' && ch > '9') && (ch != '-')) ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int main() {

#ifdef LOCAL
  FILEIO("a");
#endif

  int n; read(n);
  if ((n & (n - 1)) == 0) return puts("No"), 0;
  puts("Yes");
  printf("%d %d\n", 1 + n, 3);
  for (RI i = 2; i < n; i += 2) {
    printf("%d %d\n", i, 1);
    printf("%d %d\n", i + 1, i);
    printf("%d %d\n", i + 1 + n, 1);
    printf("%d %d\n", i + n, i + 1 + n);
  }
  if (!(n & 1)) {
    for (RI i = 1; i < n; ++i) {
      int j = n ^ i ^ 1;
      if (1 <= j && j < n) {
        printf("%d %d\n", i + (i & 1 ? 1 : 0) * n, n);
        printf("%d %d\n", j + (j & 1 ? 1 : 0) * n, n + n);
        break;
      }
    }
  }

  cerr << (double)(clock()) / CLOCKS_PER_SEC * 1000 << "ms" << endl;

  return 0;
}

