int N;

int lsb(int x) { return x & (-x); }

bool isPower2(int x) {
  return (x ^ lsb(x)) == 0;
}

void out(int x, int y) {
  cout << x << " " << y << "\n";
}

void printOdd(int n) {
  out(1, 2);
  out(2, 3);
  out(N+1, N+2);
  out(N+2, N+3);
  out(N+3, 1);
  for (int k = 4; k < n; k += 2) {
    out(1, k);
    out(k, k+1);
    out(N+k, N+k+1);
    out(N+k+1, 1);
  }
}

void printEven(int n) {
  printOdd(n-1);
  int x = n ^ lsb(n);
  int y = n - x;
  out(y, n);
  out(N + x + 1, N + n);
}

