    G[v].push_back(u);
}

int main()
{
    int n; cin >> n;

    if (n <= 2) {
        // n = 1, 2は不可能
        cout << "No" << endl;
        return 0;
    }

    if (!(n & (n-1))) {
        // 2の冪は不可能
        cout << "No" << endl;
        return 0;
    }

    vector<vector<int>> G(2*n+1);
    add_edge(G,1,2);
    add_edge(G,2,3);
    add_edge(G,3,1+n);
    add_edge(G,1+n,2+n);
    add_edge(G,2+n,3+n);

    for (int k = 4; k+1 <= n; k += 2) {
        add_edge(G,k,k+1);
        add_edge(G,k+1,1+n);
        add_edge(G,k+n,k+1+n);
        add_edge(G,k+n,1+n);
    }

    if (n % 2 == 0) {
        int tmp = n, u = 1;
        while (tmp>>1 > 0) {
            tmp >>= 1;
            u <<= 1;
        }
        int v = n ^ u ^ 1;
        if (u % 2 == 0) {
            swap(u,v);
        }
        // u: 奇数, v: 偶数
        add_edge(G,n,u);
        add_edge(G,2*n,v+n);
    }

    cout << "Yes" << endl;
    for (int u = 1; u <= 2*n; ++u) {
        for (auto v : G[u]) {
            if (u < v) {
                printf("%d %d\n", u, v);
