int main() {
    int n;
    cin >> n;
    if (n <= 2) {
        cout << "No"
             << "\n";
        return 0;
    }
    if (__builtin_popcount(n) == 1) {
        cout << "No"
             << "\n";
        return 0;
    }
    vector<pii> edges;
    edges.emplace_back(1, 2);
    edges.emplace_back(2, 3);
    edges.emplace_back(3, 1 + n);
    edges.emplace_back(1 + n, 2 + n);
    edges.emplace_back(2 + n, 3 + n);
    for (int i = 4; i <= n - 1; i += 2) {
        edges.emplace_back(i, i + 1);
        edges.emplace_back(i + 1, 1 + n);
        edges.emplace_back(1 + n, n + i);
        edges.emplace_back(n + i, n + i + 1);
    }
    if (n % 2 == 0) {
        ll x = n ^ 1;
        for (int i = 2; i < n; ++i) {
            ll y = x ^ i;
            if (y < n) {
                if (y % 2 == 0)
                    edges.emplace_back(n + y, n);
                else
                    edges.emplace_back(y, n);

                if (i % 2 == 0)
                    edges.emplace_back(n + i, 2 * n);
                else
                    edges.emplace_back(i, 2 * n);

                break;
            }
        }
    }
    cout << "Yes"
         << "\n";
    assert((int)edges.size() == 2 * n - 1);
    for (auto &p : edges) {
        cout << p.first << " " << p.second << "\n";
    }
    return 0;
}

