void die() {
  cout << "No\n";
  exit(0);
}

void solve() {
  int n;
  cin >> n;
  if(n%2 == 0) die();
  cout << "Yes\n";
  if(n%4 == 3) {
    for(int i = 2; i <= 2*n; i++) {
      cout << i-1 << " " << i << "\n";
    }
    return;
  }
  cout << "3 1\n";
  cout << "1 2\n";
  cout << 2 << " " << (n+3) << "\n";
  cout << n+3 << " " << n+1 << "\n";
  cout << n+1 << " " << n+2 << "\n";
  int last = 2;
  int rhs = 7;
  // top chain
  while(rhs <= n) {
    cout << last << " " << rhs-3 << "\n";
    cout << rhs-3 << " " << rhs-2 << "\n";
    cout << rhs-2 << " " << rhs-1 << "\n";
    cout << rhs-1 << " " << rhs << "\n";
    last = rhs;
    rhs += 4;
  }
  cout << last << " " << rhs-3 << "\n";
  cout << rhs-3 << " " << rhs-2 << "\n";
  // bottom chain
  last = n+1;
  rhs = n+7;
  while(rhs <= 2*n) {
    cout << last << " " << rhs << "\n";
    cout << rhs << " " << rhs-1 << "\n";
    cout << rhs-1 << " " << rhs-2 << "\n";
    cout << rhs-2 << " " << rhs-3 << "\n";
    last = rhs-3;
    rhs += 4;
  }
  cout << n+3 << " " << 2*n << "\n";
  cout << 2*n << " " << 2*n-1 << "\n";
}

