typedef pair<int,int>   ii;

set<ii> E;

void addEdge(int u,int v)   {   if (u > v)  swap(u,v);  E.insert(ii(u,v));  }
void remEdge(int u,int v)   {   if (u > v)  swap(u,v);  E.erase (ii(u,v));  }

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    int n;  cin >> n;

    if((n & -n) == n)   {
        cout << "No";
        return  0;
    }
    int s = (n + 1) / 4 * 4;

    for(int i = 0 ; i < s ; i += 4) {
        if (i)  {
            addEdge(i,i + 1);   i += n;
            addEdge(i,i + 1);   i -= n;
        }

        for(int j = 1 ; j < 3 ; ++j)    {
            addEdge(i + j,i + j + 1);   j += n;
            addEdge(i + j,i + j + 1);   j -= n;
        }
        addEdge(i + 3,n + max(i,1));
        addEdge(i + 3 + n,i + 4);
    }
    remEdge(s + n - 1,s);

    if (n == s) {
        int u = n & -n;
        int v = n ^ u;

        assert(u % 4 == 0);
        assert(v % 4 == 0);

        remEdge(u + n - 1,u);

        if (u + 4 < s)  {
            remEdge(u + n + 3,u + 4);
            addEdge(u + n - 1,u + 4);
        }
        addEdge(u,v);
        addEdge(u,n);
        addEdge(v,n + n);
    }
    if (n == s + 1) {
        addEdge(n,1);   addEdge(s + n,1);
        addEdge(s,n);   addEdge(n + n,s + n);
    }
    if (n == s + 2) {
        addEdge(n,1);
        addEdge(n,s + 1);
        addEdge(s,s + 1 + n);
        addEdge(s + 1 + n,2);
        addEdge(s + 1 + n,n + n);
        addEdge(s + n,3);
    }
    cout << "Yes\n";

    for(ii  e : E)
        cout << e.X << " " << e.Y << "\n";
}

