    cout << (n ^ pw) << ' ' << pw << endl;
    cout << pw << ' ' << n + n << endl;
    cout << n + n << ' ' << n + (n ^ pw) << endl;

    // n + pw + 1
    cout << n + n << ' ' << (n ^ pw) + 1 << endl;
    cout << 1 << ' ' << n + (n ^ pw) + 1 << endl;

    // vetochka
    cout << pw << ' ' << pw + 1 << endl;
