        ans.push_back({ N + 1, N + i + 1 });
        ans.push_back({ N + i + 1, N + i });
    }

    if (N % 2 == 0) {
        //Nを最左ビットとそれ以外に分ける
        ll x = 1;
        while (x < N) {
            x *= 2;
        }
        x /= 2;
        ll y = N ^ x ^ 1;
        // N -> x -> N + 1 -> y -> Nと通れば良い
        ans.push_back({ N, x });
        ans.push_back({ N + N, (y == 3 ? y :N + y) });
    }

    assert(ans.size() == 2 * N - 1);
    for (const auto& p : ans) {
        cout << p.first << " " << p.second << endl;
    }
}

