	for(int i=1;i<n-1;i++)add_edge(i+add,i+add+1);
	for(int i=n;i<n+N-1;i++)add_edge(i,i+1);
	for(int i=n+add;i<n+add+N-1;i++)add_edge(i,i+1);
	add_edge(1+add,n);
	add_edge(1+add,n+N-1+add); 
}
void solve3(){
	N--;solve2();N++;
	add_edge(N,add+add);
	add_edge(add,n);
}
