        while(true) {
            if(a < N) a <<= 1;
            else break;
        }
        a >>= 1;
        b = N^a^1;
        // connect N - a - 1 - b' - N'
        edges.push_back({N, a});
        edges.push_back({a, 1});
        edges.push_back({1, N + b});
        edges.push_back({N + b, N + N});
    }
    for(auto &e : edges) {
        cout << e.first << " " << e.second << "\n";
    }
}

