            VP ans;

            FOR(i,0,m-2) {
                ans.pb({seq[i], seq[i+1]});
            }

            ans.pb({seq[m-1], seq[0] + n});

            FOR(i,0,m-2) {
                ans.pb({seq[i] + n, seq[i+1] + n});
            }

            FOR(j,0,SIZE(need)-1) {
                auto r = res[j];

                ans.pb({seq[r.st], need[j]});
                ans.pb({seq[r.nd], need[j] + n});
            }

            return ans;
        }
    }

    return {};
}

int main() {
    ios_base::sync_with_stdio(false);

    int n;
    cin >> n;

    auto ans = solve(n);

    if (!ans.empty()) {
        cout << "Yes\n";

        for (auto &e : ans) {
            cout << e.st << ' ' << e.nd << '\n';
        }
    } else {
        cout << "No\n";
    }

    return 0;
}

