	if (N % 4 == 2) return {};

	vector<pair<int, int>> ans;
	if (N % 4 == 1) {
		rep(i, 1, N - 2) ans.push_back({ i, i + 1 });
		rep(i, 1, N - 2) ans.push_back({ i + N, i + 1 + N });
		ans.push_back({ N - 2, N + 1 });

		ans.push_back({ N, N - 1 });
		ans.push_back({ N - 1, N + 1 });

		ans.push_back({ N + 1, N + N });
		ans.push_back({ N + N, N + N - 1 });
	} else if(N % 4 == 3) {
		rep(i, 1, N) ans.push_back({ i, i + 1 });
		rep(i, 1, N) ans.push_back({ i + N, i + 1 + N });
		ans.push_back({ N, N + 1 });
	}
	else if (N % 4 == 0) {
		rep(i, 1, N - 1) ans.push_back({ i, i + 1 });
		rep(i, 1, N - 1) ans.push_back({ i + N, i + 1 + N });
		ans.push_back({ N - 1, N + 1 });

		// todo
	}

	return ans;
}
