bool power_of_two(ll N){
  if(N==2) return true;
  if(N%2==0) return power_of_two(N/2);
  return false;
}

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N;
  IN(N);

  if(N==1 || N==2){
    OUT("No");
    return 0;
  }

  if(power_of_two(N)){
    OUT("No");
    return 0;
  }

  /*
  ll tmp = 0;
  ll bor = 0;
  REP(i,N){
    bor ^= (i+1);
    if(bor==0) tmp = i+1;
  }
  */

  ll tmp = 1;
  while(tmp*2 <= N+1) tmp*=2;
  tmp--;

  vb flags(tmp+1, true);
  vll ans;
  ll hoge = (N^(N-1));
  ll tmptmp = 1;
  ll tmptmp_last = 1;
  while(tmptmp<=hoge){
    if((tmptmp&hoge)!=0){
      ans.push_back(tmptmp);
      flags[tmptmp] = false;
      tmptmp_last = tmptmp;
    }
    tmptmp*=2;
  }

  REP(i,tmp){
    if(flags[i+1]) ans.push_back(i+1);
  }

  OUT("Yes");
  REP(i, tmp-1){
    OUT(ans[i], ans[i+1]);
    OUT(ans[i]+N, ans[i+1]+N);
  }
  OUT(ans[tmp-1], 1+N);

  tmp++;
  while(tmp+1<=N){
    OUT(tmp, tmp+1);
    OUT(tmp+N, tmp+1+N);
    OUT(tmp+1, 1);
    OUT(1, tmp+N);
    tmp+=2;
  }

  if(N%2==0){
    OUT(N, N-1);
    OUT(tmptmp_last, 2*N);
  }

  return 0;
}

