void build_odd_tree(int n, vector<edge>& edges) 
{
    for (int i=2; i<=n; i++) {
        edges.push_back({1,i}); 
        edges.push_back({i,(i^1)+n}); 
    }   
    edges.push_back({3+n, 1+n}); 
}

int32_t main()
{
    #ifdef DEBUG
    //freopen("C.txt","r",stdin);
    //freopen("","w",stdout);
    #endif
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n; 
    cin >> n; 
    vector<edge> edges; 

    if (n < 3) {
        cout << "No" << endl; 
        return 0; 
    }
    else if (n%2 == 1) {
        build_odd_tree(n, edges); 
    }
    else if (n%2 == 0) {
        build_odd_tree(n-1, edges); 


        // find first 1 bit 
        int bit = 0; 
        for (; bit <= 20; bit++) {
            if (n & (1<<bit)) 
                break; 
        }
        int a = 1<<bit; 
        int b = n ^ a; 
        if (b == 0) {
            // means n is a power of 2 
            cout << "No" << endl; 
            return 0; 
        }
        // connect n nodes through the path n -- a -- 1 -- 1^b -- n
        edges.push_back({a,n}); 
        edges.push_back({1^b, n+n});   
    }

    cout << "Yes" << endl; 
    for (edge e : edges) {
        cout << e.first << " " << e.second << endl;
    }
    return 0;
}

