void sub() {
	int k = 1;
	while (k < N) {
		k *= 2;
	}
	if (N == k) {
		cout << "No" << endl;
		return;
	}
	cout << "Yes" << endl;

	k /= 2;
	if (N % 2 == 0) {
		if (N % 4 == 0) {
			vector<int> v = { k, N ^ k };
			REP(i, 1, N) {
				if (i == k || i == (N ^ k)) continue;
				v.push_back(i);
			}
			const int M = v.size();
			REP(i, 0, M) v.push_back(v[i] + N);

			REP(j, 1, v.size()) {
				print(v[j - 1], v[j]);
			}
			print(k, N);
			print(N ^ k, N + N);
		} else {
			vector<int> v = { 2, N - 1 };
			REP(i, 2, N) {
				if (i == 2 || i == N - 1) continue;
				v.push_back(i);
			}
			const int M = v.size();
			REP(i, 0, M) v.push_back(v[i] + N);

			REP(j, 1, v.size()) {
				print(v[j - 1], v[j]);
			}

			print(2, 1);
			print(1, N);
			print(N - 1, N + N);
			print(N + N, N + 1);
		}
	} else {
		for (int k = 2; k <= N; k += 2) {
			print(1, k);
			print(k, k + 1);
			print(1, N + k + 1);
			print(N + k + 1, N + k);
		}
		print(3, N + 1);
	}
}

