				P(i + 1, n + 1); P(n + i, i + 1);
			}
			if (n % 2 == 0) {
				for (int i = 2; i < n; ++i) {
					if (n & (i ^ 1)) {
						int a = i;
						int b = n ^ i ^ 1;
						P(i, a); P(n + i, b);
						break;
					}
				}
			}
		}
	}
	return 0;
}

