void dfs(vector<vector<int> > &graph, int now, int layer, vector<P> &vertex) {
	vertex[now].first = layer;

	for(int i=0; i<graph[now].size(); i++) {
		int next = graph[now][i];
		if (vertex[next].first == 0) {
			// if it is the first time to visit next vertex
			dfs(graph, next, layer+1, vertex);
			if (vertex[next].second%2 == 0) {
				vertex[now].second += 1;
				cout << now+1 << " " << next+1 << endl;
			} else {
				vertex[next].second += 1;
				cout << next+1 << " " << now+1 << endl;
			}
		} else {
			// if the next layer is smaller than now's, decide the direction in any way
			if(vertex[next].first > vertex[now].first) {
				vertex[now].second += 1;
				cout << now+1 << " " << next+1 << endl;
			}
		}
	}
}

