void solveOdd(int n, int sh) {
  assert(n & 1);
  assert(n >= 3);
  es.push_back(make_pair(sh + n, sh + n - 1));
  es.push_back(make_pair(sh + n - 1, sh + 1));
  es.push_back(make_pair(sh + 1, n));
  es.push_back(make_pair(n, n - 1));
  es.push_back(make_pair(n - 1, 1));
  for (int i = 2; i < n - 1; i += 2) {
    es.push_back(make_pair(i + 1, i));
    es.push_back(make_pair(i, n - 1));
    es.push_back(make_pair(n, sh + i + 1));
    es.push_back(make_pair(sh + i + 1, sh + i));
  }
}

