#define range(i, m, n) for(int i = m; i < n; i++)
#define husk(i, m, n) for(int i = m; i > n; i--)

int n;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n;
  if(!(n & (n - 1))) {
    cout << "No";
    return 0;
  }
  cout << "Yes\n";
  if(n % 4 == 3) {
    range(i, 0, 2 * n - 1) {
      cout << i + 1 << " " << i + 2 << endl;
    }
    return 0;
  }
  vector<vector<int>> g(2 * n + 1);
  pair<int, int> fix = make_pair(-1, -1);
  auto cc = [&](int x, int y) {
    g[x].push_back(y);
    g[y].push_back(x);
  };
  auto add = [&](int x, int y) {
    int p = x ^ y;
    if(p >= 4 * (n / 4)) return false;
    cc(p, x);
    cc(p, y);
    cc(y, x + n);
    cc(x, y + n);
    return true;
  };
  auto pull = [&](int z) {
    range(i, 1, 4 * (n / 4)) {
      if((z ^ i) < 4 * (n / 4)) {
        cc(i, z);
        cc(z ^ i, z + n);
        fix = make_pair(i, z ^ i);
        return true;
      }
    }
    return false;
  };
  if(n % 4 == 0) {
    assert(pull(n));
  }
  if(n % 4 == 1) {
    assert(add(n, n - 1));
  }
  if(n % 4 == 2) {
    int x = -1, y = -1;
    if(add(n, n - 1)) {
      x = n, y = n - 1;
    } else if(add(n - 1, n - 2)) {
      x = n - 1, y = n - 2;
    } else {
      x = n, y = n - 2;
      assert(add(x, y));
    }
    int z = 3 * n - 3 - x - y;
    if(!pull(z)) {
      int p = z ^ x;
      cc(y, z);
      cc(p, z + n);
      fix = make_pair(x ^ y, p);
    }
  }
  int sz = 4 * (n / 4);
  set<int> a;
  range(i, 1, sz) {
    a.insert(i);
  }
  if(fix.first != -1) {
    a.erase(fix.first); a.erase(fix.second);
  }
  vector<int> b;
  if(fix.first != -1) {
    b.push_back(fix.first);
    b.push_back(fix.second);
  }
  for(int i : a) b.push_back(i);
  int t = b.size();
  range(i, 0, t) b.push_back(b[i] + n);
  int c = -1;
  for(auto i : b) {
    if(c != -1) {
      cc(c, i);
    }
    c = i;
  }
  range(i, 1, 2 * n + 1) {
    for(int j : g[i]) if(j > i) cout << i << " " << j << endl;
  }
  return 0;
}

