    ae(N + 1, N + 2);
    ae(N + 3, N + 2);

    for (int i = 4; i + 1 <= N; i += 2) {
        ae(i, i + 1);
        ae(N + i, N + i + 1);
        ae(i + 1, i ^ (i + 1));
        ae(i ^ (i + 1), N + i);
    }

