int n;
bool visited[1000000];

int main(){
	scanf("%d", &n);
	bool valid = true;
	for(int i = 0; (1<<i) <= n; ++i){
		if((1<<i) == n)
			valid = false;
	}
	if(valid){
		/*
		Mark 1 as root, make a line tree with this pattern
		... - 4 - 5 - 2 - 3 - 1 - 2 - 3 - 4 - 5 - ...
					  |
					  1
		This should work for all odd value n.
		Note that the all pair can be placed in arbritrary order. That means this sequence:
		... - 7 - 6 - 2 - 3 - 4 - 5 - 1 - 4 - 5 - 2 - 3 - 7 - 6 - ...
		is also valid.

		For even n:
		Let LS be the least significant bit of N. Then, make sure that node LS and node (n-LS)
		is adjacent. Then, make this pattern:
		... - LS - (n-LS) - ...
			  |		 |
			  N 	 N
		*/
		printf("Yes\n");
		int l = 1, r = 1;
		if(n%2 == 0){
			int LS = (n&(-n));
			// Both LS and n-LS must be even
			visited[LS] = visited[LS+1] = visited[n-LS] = visited[n-LS+1] = true;
			printf("%d %d\n", LS+1, LS);
			printf("%d %d\n", LS, n-LS);
			printf("%d %d\n", n-LS, n-LS+1);
			printf("%d %d\n", n-LS+1, 1);
			printf("%d %d\n", 1, n+(n-LS));
			printf("%d %d\n", n+(n-LS), n+(n-LS+1));
			printf("%d %d\n", n+(n-LS+1), n+(LS+1));
			printf("%d %d\n", n+(LS+1), n+LS);
			l = LS+1, r = n+LS;

			printf("%d %d\n", n, LS);
			printf("%d %d\n", n+n, n-LS);

			printf("%d %d\n", n+1, LS+1);
		}
		for(int i = 2; i < n; i += 2) if(!visited[i]){
			visited[i] = visited[i+1] = true;
			printf("%d %d\n", i, i+1);
			printf("%d %d\n", i+1, l);
			printf("%d %d\n", r, n+i);
			printf("%d %d\n", n+i, n+i+1);
			l = i, r = n+i+1;
		}
		if(n%2 == 1){
			printf("%d %d\n", n+1, 2);
		}
	}else{
		printf("No\n");
	}
}

