int beki(int N) {
	while (N > 1) {
		if (N % 2 != 0)return 0;
		N /= 2;
	}
	return 1;
}
int keta(int N) {
	int res = 0;
	while (N > 0) {
		res++;
		N /= 2;
	}
	return res;
}

