		return 0;
	}
	vector<pair<int,int>> E;
	if(N%4==1){
		for(int i=2;i<=N;i+=2){
			E.emplace_back(1,i);
			E.emplace_back(i,i+1);
			E.emplace_back(1,N+i+1);
			E.emplace_back(N+i+1,N+i);
		}
		E.emplace_back(N+1,3);
	}
	else if(N%4==3){
		vector<int> a;
		for(int i=0;i<=N;i+=4){
			if(i!=0)a.push_back(i);
			for(int j=0;j<2;j++){
				for(int k=0;k<3;k++){
					a.push_back(i+1+k);
				}
			}
			if(i!=0)a.push_back(i);
		}
		vector<bool> used(N+5,false);
		used[a[0]]=true;
		for(int i=1;i<a.size();i++){
			if(used[a[i]]){
				a[i]+=N;
			}
			else{
				used[a[i]]=true;
			}
			E.emplace_back(a[i-1],a[i]);
		}
	}

	cout<<"Yes"<<endl;
	for(int i=0;i<E.size();i++)cout<<E[i].first<<' '<<E[i].second<<endl;

	return 0;
}

