int N;
using P = pair<int, int>;
vector<P> ans;

void solve(int N_) {
    if (N_ == 3) {
        ans.push_back(P{1, 2});
        ans.push_back(P{2, 3});
        ans.push_back(P{3, 1 + N});
        ans.push_back(P{1 + N, 2 + N});
        ans.push_back(P{2 + N, 3 + N});
        return;
    }
    int M = (N_ >> 1) + 1;
    for (int i = M; i < N_; ++i) ans.push_back(P{i, i + 1});
    ans.push_back(P{N_, M + N});
    for (int i = M; i < N_; ++i) ans.push_back(P{i + N, i + 1 + N});
    if (N_ != 7) ans.push_back(P{N_ + N, M >> 1});
    else ans.push_back(P{N_ + N, 1});
    solve(N_ >> 1);
}

