}
int main(){
    int n;
    cin>>n;
    if(n<=2){
        No();
        return 0;
    }
    int m=1;
    while(m<=n) m*=2;
    cerr<<m<<endl;
    int upper=n-m/2;
    if(upper%2==0){
        No();
        return 0;
    }

    vector<pair<int,int>> res;
    auto line=[&res](int l,int r){
        for(int i=l;i<r;i++){
            res.push_back({i,i+1});
        }
    };
    if(n==m-1){
        line(1,n);
        res.push_back({n,n+1});
        line(n+1,2*n);
    }
    else{
