        for(int i=n+1;i<m;i++){
            piyo^=i;
        }
        assert(piyo);
        line(1,m/2-1);
        res.push_back({m/2-1,n+1});
        line(n+1,n+m/2-1);
        line(m/2,n);
        res.push_back({n,piyo});
        res.push_back({piyo,n+m/2});
        line(n+m/2,n+n);
    }
    cout<<"Yes"<<endl;
    for(auto p:res){
        cout<<p.first<<" "<<p.second<<endl;
    }    
