	//node: b(center), N+b
	bool start = true;
	vector<pii> ans;
	for(int i = 1;i <= N;i++){
		if(i==b){
			continue;
		}
		int j = (i^b);
		if(i>j)continue;
		//i < j
		ans.push_back({i,b});
		ans.push_back({j,b});
		ans.push_back({i,N+j});
		ans.push_back({j,N+i});
		if(start){
			ans.push_back({N+i,N+b});
			start = false;
		}
	}
	for(auto &&e:ans){
		cout<<e.first<<" "<<e.second<<endl;
	}
}
