    i64 u = 1;
    for (; (u << 1) < n; u <<= 1);
    i64 v = n & ~u;

    // u+1 - u - v - v+1 - 1 - V - V+1 - U+1 - U
    //       |   |
    //       n   N

    e.emplace_back(u + 1, u);
    e.emplace_back(u, v);
    e.emplace_back(u, n);
    e.emplace_back(v, n + n);
    e.emplace_back(v, v + 1);
    e.emplace_back(v + 1, 1);
    e.emplace_back(1, n + v);
    e.emplace_back(n + v, n + v + 1);
    e.emplace_back(n + v + 1, n + u + 1);
    e.emplace_back(n + u + 1, n + u);
    used[u] = used[v] = true;
  }

  e.emplace_back(3, n + 1);
  for (i64 i = 2; i < n; i += 2) {
    if (used[i]) continue;
    e.emplace_back(1, i);
    e.emplace_back(i, i + 1);
