bool check(int n) {
    while (n > 1) {
        if (n%2 == 1) {
            return false;
        }
        n /= 2;
    }
    return true;
}

long long keta(int n) {
    int ret = 0;
    while (n > 1) {
        n /= 2;
        ret++;
    }
    return ret;
}

