        vector<int> nums;
        for (int i = 2; i <= n; i *= 2) {
            if ((n & i) == i) {
                used[i] = true;
                used[n + i] = true;
                nums.pb(i);
            }
        }
        used[n] = true;
        int ev = 2;
        while (used[ev]) {
            ev += 2;
        }
        used[ev] = used[ev + 1] = used[ev + n] = used[ev + n + 1] = true;
        int pre = -1;
        for (int x : nums) {
            if (pre != -1) {
                printf("%d %d\n", pre, x);
            }
            pre = x;
        }
        printf("%d %d\n", pre, n);
        pre = n;
        for (int x : nums) {
            printf("%d %d\n", pre, x + n);
            pre = x + n;
        }
        pre = n;
        for (int i = 1; i <= 2 * n; ++i) {
            if (!used[i]) {
                printf("%d %d\n", pre, i);
                pre = i;
            }
        }
        printf("%d %d\n", ev, ev + 1);
        printf("%d %d\n", ev + 1, 1);
        printf("%d %d\n", 1, ev + n);
        printf("%d %d\n", ev + n, ev + n + 1);
    }
    return 0;
}

