    vector<int> twoSum(vector<int>& nums, int target) {
        int i=0,j=0;
        vector<int> ans;
        int k=0;
        for(i=0;i<nums.size();i++){
            for(j=i;j<nums.size();j++){ 
                if(i!=j && (nums[i]+nums[j] == target ) ){
                    ans.push_back(i);
                    ans.push_back(j);
                    k=0;
                    break;
                }
                k++;
            }
            if(k==0) break;
        }
        return ans;
    }
