int digit(int n) {
    int ans = 0;
    while (n > 0) {
        n >>= 1;
        ans++;
    }
    return ans;
}

void answer(const vPi &edges) {
    cout << "Yes" << endl;
    dump(edges.size());
    for (auto p : edges) {
        cout << p.first << " " << p.second << endl;
    }
