    auto edges = solve(n);
    if (edges.empty()) {
        assert (false);
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
        for (auto e : edges) {
            cout << e.first << ' ' << e.second << endl;
        }
    }
    return 0;
}

