void dfs(ll now) {
	visited[now] = true;
	for (auto e : es[now]) {
		if (!visited[e]) {
			dfs(e);
			if (dim[e] % 2) {
				rev[P(min(now, e), max(now, e))] ^= true;
				dim[e]++;
				dim[now]++;
			}
		}
