	ios::sync_with_stdio(false);
	ll N;
	cin >> N;
	ll high = 1;
	while (high * 2 <= N)
		high *= 2;
	if (high == N)
		cout << "No" << endl;
	else {
		cout << "Yes" << endl;
		vector<P> es;
		set<ll> part;
		for (ll i = 0;i < (N + 1) / 4;i++) {
			part.insert(i);
			for (ll j = i * 4;j < i * 4 + 3;j++) {
				if (j == 0)
					continue;
				es.push_back(P(j, j+1));
				es.push_back(P(j + N, j + N + 1));
			}
			es.push_back(P(i * 4 + 3, max(1LL, i * 4) + N));
		}
		if (N % 4 == 0) {
			ll rest = N - high;
			part.erase(part.find(rest / 4));
			es.push_back(P(rest, high));
			es.push_back(P(N, rest));
			es.push_back(P(N + N, high));
		}
		else if (N % 4 == 1) {
			es.push_back(P(N-1, N));
			es.push_back(P(N, 1));
			es.push_back(P(1, N-1+N));
			es.push_back(P(N-1+N, N + N));
		}
		else if (N % 4 == 2) {
			es.push_back(P(N - 2, N-1));
			es.push_back(P(N-1, 1+N));
			es.push_back(P(1+N, N - 2 + N));
			es.push_back(P(N - 2 + N, N -1 + N));
			es.push_back(P(N, N - 2 + N));
			es.push_back(P(N+N, 3));
		}
		while (part.size() > 1) {
			auto ite = part.begin();
			ll f = *ite;
			ite++;
			es.push_back(P(max(1LL, f * 4), max(1LL, *ite * 4)));
			part.erase(ite);
		}
