int N;

bool isPowerOf2(ll n) {
    while ((n&1) == 0) n >>= 1;
    return n == 1;
}

inline bool include(set<int> s, int x) {
    return s.find(x) != s.end();
}

ii split(int n) {
    int k = 1;
    while (k < n) k <<= 2;
    k >>= 2;
    assert((k^n) != 0);
    return MP(k, (k^n)+1);
}

void solve() {
    if (isPowerOf2(N)) {
        cout << "No\n";
        return;
    }
    cout << "Yes\n";

    set<int> nextTo1;
    vii ans;
    for (int i = 2; i < N; i += 2) {
        ans.PB(MP(1, i));
        ans.PB(MP(i, i+1));
        ans.PB(MP(1, N+i+1));
        ans.PB(MP(N+i+1, N+i));

        nextTo1.insert(i);
        nextTo1.insert(N+i+1);
    }
    ans.PB(MP(3, N+1));


    FOR (i, 2, N)
        assert(include(nextTo1, i) ^ include(nextTo1, N+i));

    if (N%2 == 1) {
        assert(include(nextTo1, N) ^ include(nextTo1, 2*N));
    } else {
        ii m = split(N);
        int a = m.first, b = m.second;
        if (!include(nextTo1, a)) {
            if (a > N) a -= N;
            else a += N;
        }
        if (!include(nextTo1, b)) {
            if (b > N) b -= N;
            else b += N;
        }
        assert(include(nextTo1, a));
        assert(include(nextTo1, b));
        ans.PB(MP(a, N));
        ans.PB(MP(b, 2*N));
    }
    FORE (x, ans) {
        cout << x.first << " " << x.second << "\n";
    }
}

int main() {
    cin >> N;
    solve();
}

