vector<P> make_graph(const ll n, const vector<P>& v) {
  vector<P> res;
  // make: 0(1), v[0].first, v[0].second, 0(n), v[0].first, v[0].second
  res.eb(1, v[0].first);
  res.eb(v[0].first, v[0].second);
  res.eb(v[0].second, n+1);
  res.eb(n+1, n+v[0].first);
  res.eb(n+v[0].first, n+v[0].second);
  // make: v[i].first, v[i].second, 0(1), ..., 0(n), v[i].first, v[i].second
  rep(i, 1, v.size()) {
    res.eb(v[i].first, v[i].second);
    res.eb(v[i].second, 1);
    res.eb(n+1, n+v[i].first);
    res.eb(n+v[i].first, n+v[i].second);
  }
  return res;
}

void solve() {
  ll n; cin >> n;
  if (n < 3) {
    cout << false << endl;
    return;
  }
  if (__builtin_popcountll(n) == 1) {
    cout << false << endl;
    return;
  }
  vector<P> ans;
  if (n == 6) {
    cout << "Yes" << endl;

    cout << 4 << " " << 6 << endl;
    cout << 6 << " " << 2 << endl;
    cout << 2 << " " << n+4 << endl;
    cout << n+4 << " " << n+6 << endl;
    cout << n+6 << " " << n+2 << endl;

    cout << n+2 << " " << 1 << endl;

    cout << 1 << " " << 3 << endl;
    cout << 3 << " " << 5 << endl;
    cout << 5 << " " << n+1 << endl;
    cout << n+1 << " " << n+3 << endl;
    cout << n+3 << " " << n+5 << endl;
    return;
  }
  vector<P> v;
  for (ll i = 2; i+1 <= n; i += 2) v.eb(i, i+1);
  if (n % 2 == 1) {
    ans = make_graph(n, v);
  }
  else {
    ll x = n & -n, y = n ^ x;
    vector<P> nv;
    P xp, yp;
    each(p, v) {
      if (p.first == x || p.second == x) {
        xp = p;
      }
      else if (p.first == y || p.second == y) {
        yp = p;
      }
      else {
        nv.pb(p);
      }
    }
    assert(xp.first != xp.second);
    assert(yp.first != yp.second);
    if (xp.first == x) {
      swap(xp.first, xp.second);
    }
    if (yp.first != y) {
      swap(yp.first, yp.second);
    }
    v = nv;
    // cout << xp << endl;
    // cout << yp << endl;
    ans = make_graph(n, v);

    ans.eb(1, xp.first);
    ans.eb(xp.first, xp.second);
    ans.eb(xp.second, yp.first);
    ans.eb(yp.first, yp.second);
    ans.eb(yp.second, n+xp.first);
    ans.eb(n+xp.first, n+xp.second);
    ans.eb(n+xp.second, n+yp.first);
    ans.eb(n+yp.first, n+yp.second);

    ans.eb(x, n);
    ans.eb(y, n+n);
  }
  cout << "Yes" << endl;
  each(p, ans) {
    cout << p.first << " " << p.second << endl;
  }
}

