signed main(){

    int N; cin >> N;
    int d;
    REP(i, 100){
        if(N <= bit(i)){
            d = i;
            break;
        }
    }
    if(N == bit(d)){
        Out("No");
        return 0;
    }

    //N>=3
    pairs ans;
    ans.pb(Pii(1, 3));
    ans.pb(Pii(3, 2));
    ans.pb(Pii(2, 1 + N));
    ans.pb(Pii(1 + N, 3 + N));
    ans.pb(Pii(3 + N, 2 + N));

    for(int i = 4; i <= N; i += 2){
        if(i + 2 == N){
            if((N >> 1) & 1){
                ans.pb(Pii(i, 1));
                ans.pb(Pii(i + 1, i));
                ans.pb(Pii(i + 1 + N, i + N));
                ans.pb(Pii(i + 1 + N, 1 + N));
                ans.pb(Pii(i + 2, i));
                ans.pb(Pii(i + 2 + N, 3));
            }else{
                ans.pb(Pii(i + 2, 1));
                ans.pb(Pii(i + 1, i + 2));
                ans.pb(Pii(i + 1 + N, i + 2 + N));
                ans.pb(Pii(i + 1 + N, 1 + N));
                ans.pb(Pii(i, i + 2));
                ans.pb(Pii(i + N, 3));
            }
            break;
        }else{
            ans.pb(Pii(i, 1));
            ans.pb(Pii(i + 1, i));
            ans.pb(Pii(i + 1 + N, i + N));
            ans.pb(Pii(i + 1 + N, 1 + N));
        }
    }

    Out("Yes");
    REP(i, 2 * N - 1) cout << ans[i].f << " " << ans[i].s << endl;

    return 0;
}

