void build_odd(int x, bool xtra = false)
{
    if (!xtra)
    {
        e(3, 1);
        e(1, 2);
        e(2, 3 + n);
        e(3 + n, 1 + n);
        e(1 + n, 2 + n);
        // T(3) is ready
        for (int y = 4; y + 1 <= x; ++y)
        {
            e(y, 1);
            e(y + 1, y);
            e(1 + n, y + 1 + n);
            e(y + 1 + n, y + n);
        }
    }
    else
    {
        e(5, 1);
        e(1, 4);
        e(4, 5 + n);
        e(5 + n, 1 + n);
        e(1 + n, 4 + n);
        e(2, 1);
        e(3, 2);
        e(1 + n, 3 + n);
        e(3 + n, 2 + n);
        // T(5) is ready
        for (int y = 6; y + 1 <= x; ++y)
        {
            e(y, 1);
            e(y + 1, y);
            e(1 + n, y + 1 + n);
            e(y + 1 + n, y + n);
        }
    }
}

