void build(int n)
{
   // cout<< n <<" "<< m <<"\n";
    if(n&1)
    {
        if(n > 3)
            build(n-2);
    }
    else
    {
        /// m = 2^t;
        if(n == m+2)
        {
          //  cout<< n <<" "<< m <<"\n";
            edge.push_back({m,m+1});
            edge.push_back({m,1});
            edge.push_back({m,2});
            edge.push_back({m,m+2});

            edge.push_back({N+2,m+2});
            edge.push_back({N+m+2,2});
            edge.push_back({N+m+1,1});
            edge.push_back({N+1,m+1});

            edge.push_back({N+m,N+m+1});

            edge.push_back({3,1});
            edge.push_back({N+3,m+2});

            for(int i = 4; i < m; i += 2)
            {
                edge.push_back({i,1});
                edge.push_back({i-1,1});
                edge.push_back({N+i,i-1});
                edge.push_back({N+i-1,i});
            }

            return;
        }
        else
        {
        //   cout<< n <<" ";
            build(n-2);
        }
    }

//    cout<< edge.size() <<"\n";

    int x = (n ^ (n-1));
    edge.push_back({x,n-1});
    edge.push_back({x,n});
    edge.push_back({n, n-1+N});
    edge.push_back({N+n, n-1});
    if(n == 3)
        edge.push_back({N+1,N+3});
}

