	if (nn == 1) cout << "No\n";
	else {
		// build chain of 1 to 3
		ans.push_back({ 1, 2 });
		ans.push_back({ 2, 3 });
		ans.push_back({ 3, n + 1 });
		ans.push_back({ n + 1, n + 2 });
