			ans.push_back({ i, n + i + 1 });
			ans.push_back({ i + 1, n + 1 });
			ans.push_back({ n + i, i + 1 });
		}

		if (n % 2 == 0) {
			// find the last 1-bit of n
			x = 1;
			while (!(x & n)) x *= 2;

			ans.push_back({ x + 1, n });
			ans.push_back({ n - x, n + n });
		}

		cout << "Yes\n";
		for (auto p : ans) cout << p.first << " " << p.second << "\n";
	}



	return 0;
}

