    two_pow.insert(x);
    if (x == n) {
      cout << "No" << endl;
      return 0;
    }
    x *= 2;
  }

  ll m = (n + 1) / 4 * 4 - 1;
  if (n == m) {
    solve_easy(n);
    return 0;
  }
  if (not two_pow.count(m + 1)) {
    solve1(n, m);
