void dfs(int v, int t, int x, int& ans) {
  used[v] = 1;
  if (v > n) {
    x ^= (v - n);
  } else {
    x ^= v;
  }
  if (v == t) {
    ans = x;
  }
  for (auto it : lst[v]) {
    if (used[it]) {
      continue;
    }
    dfs(it, t, x, ans);
  }
}
