		ans.push_back({ n,r1+n });
		ans.push_back({ r1+n,r2+n });
		ans.push_back({ r2+n,n+n });
		rep1(i, 3) {
			ans.push_back({ r1 + i - 1,r1 + i });
			ans.push_back({ r2 + i - 1,r2 + i });
		}
