		//cout << ans.size() << endl;
		rep(i, 2 * n - 1) {
			cout << ans[i].first << " " << ans[i].second << endl;
		}
	}
	else if (n % 4 == 1) {
		ans.push_back({ 1,2 });
		ans.push_back({ 2,3 });
		int tmp = 4; int loc = 3;
		while (tmp < n-1) {
			ans.push_back({ loc,tmp });
			ans.push_back({ tmp,tmp+1 });
			ans.push_back({ tmp+1,tmp+2 });
			ans.push_back({ tmp+2,tmp+3 });
