		ans.push_back({ n + 1,n + 2 });
		ans.push_back({ n + 2,n + 3 });
		tmp = 4; loc = 3;
		while (tmp < n-1) {
			ans.push_back({ n+loc,n+tmp });
			ans.push_back({ n+tmp,n+tmp + 1 });
			ans.push_back({ n+tmp + 1,n+tmp + 2 });
			ans.push_back({ n+tmp + 2,n+tmp + 3 });
			loc = tmp + 3; tmp += 4;
		}
		ans.push_back({ 1,n - 1 }); ans.push_back({ n - 1,n });
		ans.push_back({ 1,n + n }); ans.push_back({ n + n,n + n - 1 });
		cout << "Yes" << endl;
		//cout << ans.size() << endl;
		rep(i, 2 * n - 1) {
			cout << ans[i].first << " " << ans[i].second << endl;
		}
	}
	else {
