				r1 = (1 << j);
				break;
			}
		}
		int r2 = r1 ^ (n-2);
		ans.push_back({ r1,r2 });
		ans.push_back({ r2,(n-2) });
		ans.push_back({ n-2,r1 + n });
		ans.push_back({ r1 + n,r2 + n });
		ans.push_back({ r2 + n,n + (n-2) });
		rep1(i, 3) {
			ans.push_back({ r1 + i - 1,r1 + i });
			ans.push_back({ r2 + i - 1,r2 + i });
		}
		ans.push_back({ r1 + n,r1 + n + 3 });
		ans.push_back({ r1 + n + 3,r1 + n + 2 });
		ans.push_back({ r1 + n + 2,r1 + n + 1 });
		ans.push_back({ r2 + n,r2 + n + 3 });
		ans.push_back({ r2 + n + 3,r2 + n + 2 });
		ans.push_back({ r2 + n + 2,r2 + n + 1 });
		int tmp = 0;
		ans.push_back({ r1,1 });
		ans.push_back({ 1,2 });
		ans.push_back({ 2,3 });
		tmp = 4; int loc = 3;
		while (tmp < n-2) {
			if (tmp == r1 || tmp == r2) {
				tmp += 4; continue;
			}
			ans.push_back({ loc,tmp });
			ans.push_back({ tmp,tmp + 1 });
			ans.push_back({ tmp + 1,tmp + 2 });
			ans.push_back({ tmp + 2,tmp + 3 });
			loc = tmp + 3;
			tmp += 4;
		}
		ans.push_back({ loc,n + 1 });
		ans.push_back({ n + 1,n + 2 });
		ans.push_back({ n + 2,n + 3 });
		tmp = 4; loc = 3;
		while (tmp < n-2) {
			if (tmp == r1 || tmp == r2) {
				tmp += 4; continue;
			}
			ans.push_back({ n + loc,n + tmp });
