using ll = std::int64_t;
using P = std::tuple<int,int>;

int N;
std::vector<P> G;

bool can(){
    if(N == 1){
        return false;
    }

    unless(N % 2 == 1 || __builtin_popcount(N) >= 2){
        return false;
    }

    for(int i=2;i+1<=N;i+=2){
        G.emplace_back(1, i);
        G.emplace_back(i, i + 1);
        G.emplace_back(1, i + 1 + N);
        G.emplace_back(i + 1 + N, i + N);
    }

    G.emplace_back(3, 1 + N);

    if(N % 2 == 0){
        int u = N & -N, v = N ^ u;
        G.emplace_back(u, N);
        G.emplace_back(v, N * 2);
    }

    return true;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    if(can()){
        std::cout << "Yes" << std::endl;

        for(auto &p : G){
            int u, v;
            std::tie(u, v) = p;

            std::cout << u << " " << v << std::endl;
        }
    }else{
        std::cout << "No" << std::endl;
    }
}

