int n;
vector<pii> ans;

void solve(vi a, int id) {

    if (SZ(a) & 1) {
        ans.push_back({a[0], a[1]});
        ans.push_back({a[1], a[2]});
        ans.push_back({a[2], a[0] + n});
        ans.push_back({a[0] + n, a[1] + n});
        ans.push_back({a[1] + n, a[2] + n});


        for (int i = 3; i < SZ(a); i += 2) {
            ans.push_back({a[i + 1], a[i]});
            ans.push_back({a[i], a[0]});
            ans.push_back({a[0], a[i + 1] + n});
            ans.push_back({a[i + 1] + n, a[i] + n});
        }
    } else {
        vi f, s;
        for (auto x : a) {
            if ((x >> id) & 1)
                f.push_back(x);
            else
                s.push_back(x);
        }
        ans.push_back({f[0], s[0]});
        solve(f, id + 1);
        solve(s, id + 1);
    }
}

void smain() {

    cin >> n;
    int pw = 0;
    while ((1 << pw) <= n) {
        pw++;
    }
    pw--;
    if (n == (1 << pw)) {
        cout << "No\n";
        return;
    }


    vi a(n);
    fori (i, n) {
        a[i] = i + 1;
    }
    solve(a, 0);

    cout << "Yes\n";
    for (auto x : ans) {
        cout << x.first << ' ' << x.second << '\n';
    }
}

