			pas[vec[i-lar].se] = i+n;
			pas[lar] = i;
			vec.push_back({i^lar, i});
		}
	}
	for(int i = 1;  i <= n; i = i+i)
	{
		if(pas[i] <= n)
			ans.push_back({i+n, pas[i]+n});
		else
			ans.push_back({i+n, pas[i]-n});
	}

	for(auto i : ans) printf("%d %d\n", i.fi, i.se);
}

