using namespace std;

vector<pair<int, int> > solve(int n) {
    assert (n >= 10);
    if (__builtin_popcount(n) == 1) return vector<pair<int, int> >();
    vector<pair<int, int> > edges;
    REP (i, (n - 1) / 2) {
        int a = 2 * i + 2;
        int b = 2 * i + 3;
        edges.emplace_back(1, a);
        edges.emplace_back(a, b);
        edges.emplace_back(1, n + b);
        edges.emplace_back(n + b, n + a);
    }
    edges.emplace_back(3, 1 + n);
    if (n % 2 == 0) {
        edges.emplace_back(2, n);
        edges.emplace_back(n + (n - 1), n + n);
    }
    return edges;
}

int main() {
    int n; cin >> n;
    auto edges = solve(n);
    if (edges.empty()) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
        for (auto e : edges) {
            cout << e.first << ' ' << e.second << endl;
        }
    }
    return 0;
}

