  }

  if(power_of_two(N)){
    OUT("No");
    return 0;
  }

  ll tmp = 0;
  ll bor = 0;
  REP(i,N){
    bor ^= (i+1);
    if(bor==0) tmp = i+1;
  }

  OUT("Yes");
  REP(i, tmp-1){
    OUT(i+1, i+2);
    OUT(i+1+N, i+2+N);
  }
  OUT(tmp, 1+N);

  tmp++;
  while(tmp+1<=N){
    OUT(tmp, tmp+1);
    OUT(tmp+N, tmp+1+N);
    OUT(tmp+1, 1);
    OUT(1, tmp+N);
    tmp+=2;
  }

  return 0;
}

