            x *= 2;
        }
        x /= 2;
        ll y = N ^ x ^ 1;
        // N -> x -> N + 1 -> y -> Nと通れば良い
        ans.push_back({ N, x });
        ans.push_back({ N + N, (y == 3 ? y :N + y) });
    }

    assert(ans.size() == 2 * N - 1);
