    int n = ni();
    if (n == 1) {
      out.println("No");
      return;
    }
    List<int[]> ret = new ArrayList<>();
    int d = n % 2 == 0 ? 1 : 0;
    for (int i = 2; i <= n - d; i++) {
      ret.add(new int[] {1, i});
    }

    for (int i = 2; i <= n - d; i++) {
      ret.add(new int[] {i, i + n + (i % 2 == 0 ? 1 : -1)});
    }

    if (d == 1) {
      boolean flg = false;
      for (int a = 2; a <= n - 1; a++) {
        int b = n ^ 1 ^ a;

        if (a < b && b <= n - 1) {
          ret.add(new int[] {a, n});
          ret.add(new int[] {b, n + n});
