	// 5-4-3-2-5-4-3-2

	static void solve()
	{
		int n = ni();
		if(n % 4 == 3){
			out.println("Yes");
			for(int i = 1;i <= 2*n-1;i++){
				out.println(i + " " + (i+1));
			}
		}else if(n % 4 == 2){
			if(n == 2){
				out.println("No");
			}else{
				int[] a = new int[2*n-2];
				int p = 0;
				a[p++] = n/4*4;
				for(int i = 2;i <= n;i++){
					if(i == n/4*4)continue;
					a[p++] = i;
				}
				a[p++] = n/4*4+n;
				for(int i = 2;i <= n;i++){
					if(i == n/4*4)continue;
					a[p++] = i+n;
				}
				for(int i = 0;i < 2*n-3;i++){
					out.println(a[i] + " " + a[i+1]);
				}
				out.println(1 + " " + 2);
				out.println((n+1) + " " + 3);
				out.println(n + " " + 2);
				out.println((n+n) + " " + n/4*4);
			}
		}else if(n % 4 == 0){
			if((n&n-1) == 0){
				out.println("No");
			}else{
				int[] a = new int[2*n-2];
				int p = 0;
				int x = Integer.highestOneBit(n);
				int y = n-x;
				for(int i = 1;i <= n-1;i++){
					if(i == x)continue;
					if(i == y)continue;
					a[p++] = i;
				}
				a[p++] = x;
				a[p++] = y;
				for(int i = 1;i <= n-1;i++){
					if(i == x)continue;
					if(i == y)continue;
					a[p++] = i+n;
				}
				a[p++] = x+n;
				a[p++] = y+n;
				for(int i = 0;i < 2*n-3;i++){
					out.println(a[i] + " " + a[i+1]);
				}
				out.println(n + " " + x);
				out.println((n+n) + " " + y);
			}
		}else if(n % 4 == 1){
			if(n == 1){
				out.println("No");
			}else{
				for(int i = 2;i <= 2*n-1;i++){
					if(i == n+1)continue;
					int ne = i == n ? n+2 : i+1;
					out.println(i + " " + ne);
				}
				out.println(1 + " " + 2);
				out.println((n+1) + " " + 3);
			}
		}else{
			out.println("No");
		}
	}

