import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.InputMismatchException;

public class Main {
    InputStream is;

    int __t__ = 1;
    int __f__ = 0;
    int __FILE_DEBUG_FLAG__ = __f__;
    String __DEBUG_FILE_NAME__ = "src/C1";

    FastScanner in;
    PrintWriter out;

    ArrayList<Integer>[] g;

    public void solve() {
        int n = in.nextInt();
        int two = 1;
        while (two < n) {
            two *= 2;
        }
        if (two == n) {
            System.out.println("No");
            return;
        }
        g = new ArrayList[2*n+1];
        for (int i = 1; i <= 2 * n; i++) {
            g[i] = new ArrayList<>();
        }

        for (int j1 = 2; j1 + 1 <= n; j1 += 2) {
            int j2 = j1 + n;
            int k1 = j1 + 1;
            int k2 = k1 + n;
            add(1, k1);
            add(1, j1);
            add(k1, j2);
            add(j1, k2);
        }
        if (n % 2 == 0) {
            add((n ^ (n - 1) ^ 1), n);
            add(n - 1, n + n);
        }
        add(n+1, n+2);
        for (int u = 1; u <= 2 * n; u++) {
            for (int v : g[u]) {
                if (u < v) {
                    out.println(u + " " + v);
                }
            }
        }
        out.close();
        validate(n);
    }

    private void validate(int n) {
        for (int u = 1; u <= n; u++) {
            long xor = dfs(u, -1, u + n, n);
            if (xor != u) {
                throw new RuntimeException("Something wrong " + u + " " + xor);
            }
        }
    }

    private long dfs(int u, int prev, int target, int n) {
        if (u == target) {
            return target - n;
        }
        for (int v : g[u]) {
            if (prev == v) {
                continue;
            }
            long next = dfs(v, u, target, n);
            if (next != Long.MAX_VALUE) {
                return u > n ? (next ^ (u - n)) : (next ^ u);
            }
        }
        return Long.MAX_VALUE;
    }

    private void add(int u, int v) {
        g[u].add(v);
        g[v].add(u);
    }

    /* MOD_CALCULATION */
    static int MOD = 1_000_000_007;
    static long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    static long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    static long MULT(long a, long b) {
        return ((a % MOD) * (b % MOD)) % MOD;
    }

    static long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    static long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
    /* end */

