class Algorithm{
    public static void prYesNo(int y){
        System.out.println(y == 1 ? "Yes" : "No");
    }
    public static boolean isOdd(int n){
        return n % 2 == 1;
    }

    public static boolean isNibeki(int n){
        if (n==1){
            return true;
        }
        if(n%2==0){
            return isNibeki(n/2);
        }else {
            return false;
        }
    }
