/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Egor Kulikov (egor@egork.net)
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            if (Integer.bitCount(n) == 1) {
                out.printLine("No");
                return;
            }
            out.printLine("Yes");
            int[] a = new int[2 * n - 1];
            int[] b = new int[2 * n - 1];
            int at = 0;
            int k = (n + 1) / 4;
            for (int i = 1; i < 4 * k - 1; i++) {
                a[at] = i;
                b[at++] = i + 1;
            }
            for (int i = 2; i < 4 * k - 1; i++) {
                a[at] = i + n;
                b[at++] = i + n + 1;
            }
            a[at] = 1;
            b[at++] = 4 * k - 1 + n;
            if (n == 4 * k - 1 || n == 4 * k) {
                a[at] = n + 1;
                b[at++] = n + 2;
                if (n == 4 * k) {
                    int highest = Integer.highestOneBit(n);
                    a[at] = highest;
                    b[at++] = n;
                    a[at] = n - highest + 1;
                    b[at++] = 2 * n;
                }
            } else {
                a[at] = 1;
                b[at++] = 4 * k + 1;
                a[at] = 4 * k + 1;
                b[at++] = 4 * k;
                a[at] = 4 * k;
                b[at++] = n + 1;
                a[at] = n + 1;
                b[at++] = n + 4 * k + 1;
                a[at] = n + 4 * k + 1;
                b[at++] = n + 4 * k;
                if (n == 4 * k + 2) {
                    a[at] = 2;
                    b[at++] = 4 * k + 2;
                    a[at] = 4 * k + 1;
                    b[at++] = n + 4 * k + 2;
                }
            }
            for (int i = 0; i < 2 * n - 1; i++) {
                out.printLine(a[i], b[i]);
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

import java.util.*;
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int num = sc.nextInt();
		int tmp = num;
		while(tmp % 2 == 0) {
			tmp /= 2;
		}
		if(tmp == 1) { System.out.println("No"); return; }
		System.out.println("Yes");
		int line = (int)(Math.floor((num + 1) / 4.0) * 4) - 1;
		StringBuilder ans = new StringBuilder();
		for(int i = 1; i < line; i ++) {
			ans.append(i+" "+(i + 1)+"\n");
			ans.append((num + i)+" "+(num + i + 1)+"\n");
		}
		ans.append(line+" "+(num + 1)+"\n");
		int rest = num - line;
		switch(rest) {
		case 0: break;
		case 1:
			ans.append((num / tmp + 1)+" "+(line + 1)+"\n");
			ans.append((num - num / tmp)+" "+(num + line + 1)+"\n");
			break;
		case 2: case 3:
			ans.append((1)+" "+(line + 1)+"\n");
			ans.append((line + 1)+" "+(line + 2)+"\n");
			ans.append((num + 1)+" "+(num + line + 2)+"\n");
			ans.append((num + line + 2)+" "+(num + line + 1)+"\n");
			if(rest == 3) {
				ans.append((num + line + 2)+" "+(line + 3)+"\n");
				ans.append((num + 2)+" "+(num + line + 3)+"\n");
			}
			break;
		}
		System.out.println(ans);
	}
}

