using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		int c = 1;
		string ans = "Yes";
		for(var i=0;i<=30;i++){
			if(c==N){
				ans = "No";
				break;
			} else if(c>N){
				c /= 2;
				break;
			} else {
				c *= 2;
			}
		}
		Console.WriteLine(ans);
		if(ans=="Yes"){
			Console.WriteLine("1 2");
			Console.WriteLine("2 3");
			Console.WriteLine("3 "+(N+1));
			Console.WriteLine((N+1)+" "+(N+2));
			Console.WriteLine((N+2)+" "+(N+3));
			for(var i=3;i<=(N+1)/2;i++){
				Console.WriteLine((N+1)+" "+(i*2-1));
				Console.WriteLine((i*2-1)+" "+(i*2-2));
				Console.WriteLine((N+1)+" "+(N+i*2-2));
				Console.WriteLine((N+i*2-2)+" "+(N+i*2-1));
			}
			if(N%2==0){
				int d = N-c+1;
				Console.WriteLine(N+" "+d);
				Console.WriteLine((N*2)+" "+(c+N));
			}
		}
	}
}

using System;
using System.Collections.Generic;
using System.Text;
using System.Numerics;
using System.IO;


namespace SolutionCS
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            if ((N - 3) % 4 == 0)
            {
                Console.WriteLine("Yes");
                for (int i = 0; i < N * 2 - 1; i++)
                {
                    Console.WriteLine("{0} {1}", i + 1, i + 2);
                }

                return;
            }

            if ( N >= 5 && (N - 3) % 4 == 2) { 

                Console.WriteLine("Yes");

                for (int i = 0; i < N - 3; i++)
                {
                    Console.WriteLine("{0} {1}", i + 1, i + 2);
                    Console.WriteLine("{0} {1}", N + i + 1, N + i + 2);
                }

                Console.WriteLine("{0} {1}", N - 2, N + 1);

                Console.WriteLine("1 {0}", N);
                Console.WriteLine("{0} {1}", N, N - 1);

                Console.WriteLine("{0} {1}", N + 1, N * 2 - 1);
                Console.WriteLine("{0} {1}", N * 2 - 1, N * 2);
                return;
            }

            if (N >= 5 && (N - 3) % 4 == 3)
            {

                Console.WriteLine("Yes");

                for (int i = 0; i < N - 4; i++)
                {
                    Console.WriteLine("{0} {1}", i + 1, i + 2);
                    Console.WriteLine("{0} {1}", N + i + 1, N + i + 2);
                }

                Console.WriteLine("{0} {1}", N - 3, N + 1);

                Console.WriteLine("1 {0}", N - 1);
                Console.WriteLine("1 {0}", N);
                Console.WriteLine("{0} {1}", N - 1, N - 2);

                Console.WriteLine("{0} {1}", N + 1, N * 2 - 2);
                Console.WriteLine("{0} {1}", N * 2 - 2, N * 2 - 1);
                Console.WriteLine("{0} {1}", N * 2 - 2, N * 2);
                return;
            }

            Console.WriteLine("No");
        }
    }
}

