using System;
using System.IO;

namespace AGC35
{
    class Program3
    {
        static void Main()
        {
            var N = int.Parse(Console.ReadLine());

            if (IsPowerOfTwo(N))
            {
                Console.WriteLine("No");
                return;
            }

            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            Console.WriteLine("Yes");
            var p = GetPowerOfTwo(N);
            var twoP = (int)Math.Pow(2, p);
            for (int i = 1; i < (twoP - 1) * 2; i++)
                Console.WriteLine(i + " " + (i + 1));

            Console.WriteLine(((twoP + 1) * 2) + " " + (twoP) * 2);
            Console.WriteLine((twoP) * 2 + " 1");
            Console.WriteLine("1 " + (twoP + 1));
            Console.WriteLine((twoP + 1) + " " + (twoP));
            for (int i = twoP + 2; i <= N; i++)
            {
                Console.WriteLine((i - twoP) + " " + i);
                Console.WriteLine((i * 2) + " " + (i - 1));
            }

            Console.Out.Flush();
        }

        static bool IsPowerOfTwo(int num)
        {
            if (num <= 0)
                return false;
            return (num & (num - 1)) == 0;
        }

        static int GetPowerOfTwo(int num)
        {
            var p = 0;
            while (num <= 1)
            {
                num >>= 1;
                p++;
            }

            return p;
        }
    }
}

