static class P
{
    static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        if (n <= 100) throw new Exception();
        if (n < 3 || n % 2 != 1)
        {
            Solve(n);
            return;
        }
        List<Tuple<int, int>> res = new List<Tuple<int, int>>();
        res.Add(new Tuple<int, int>(1, 2));
        res.Add(new Tuple<int, int>(2, 3));
        res.Add(new Tuple<int, int>(3, 1 + n));
        res.Add(new Tuple<int, int>(1 + n, 2 + n));
        res.Add(new Tuple<int, int>(2 + n, 3 + n));
        for (int i = 4; i < n; i += 2)
        {
            res.Add(new Tuple<int, int>(i, i + 1));
            res.Add(new Tuple<int, int>(i + 1, 1));
            res.Add(new Tuple<int, int>(1, i + n));
            res.Add(new Tuple<int, int>(i + n, i + 1 + n));
        }
        Console.WriteLine("Yes");
        Console.WriteLine(string.Join("\n", res.Select(x => $"{x.Item1} {x.Item2}")));

    }

    static void Solve(int n)
    {
        var msb = 1;
        while (msb * 2 <= n) msb *= 2;
        if (msb == n)
        {
            Console.WriteLine("No");
            return;
        }
        List<Tuple<int, int>> res = new List<Tuple<int, int>>();
        for (int i = 1; i < msb - 1; i++)
        {
            res.Add(new Tuple<int, int>(i, i + 1));
            res.Add(new Tuple<int, int>(i + n, i + n + 1));
        }
        res[2] = new Tuple<int, int>(1, 3);
        res[3] = new Tuple<int, int>(1 + n, 3 + n);
        res.Add(new Tuple<int, int>(msb - 1, 2 + n));
        //2134...2134...
        for (int i = msb; i < n - 2; i += 2)
        {
            res.Add(new Tuple<int, int>(i, i + 1));
            res.Add(new Tuple<int, int>(i + 1, 1));
            res.Add(new Tuple<int, int>(1, i + n));
            res.Add(new Tuple<int, int>(i + n, i + 1 + n));
        }

        int lsb = (n & -n);
        if (lsb == 2)
        {
            res.Add(new Tuple<int, int>(n + n - 1, n + n));
            res.Add(new Tuple<int, int>(lsb - 1, n + n - 1));
            res.Add(new Tuple<int, int>(n, lsb));
            res.Add(new Tuple<int, int>(n - 1, n));
            res.Add(new Tuple<int, int>(n + n - 1, n - 2));
            res.Add(new Tuple<int, int>(1, n + n - 2));
        }
        else
        {
            res.Add(new Tuple<int, int>(n + n - 1, n + n));
            res.Add(new Tuple<int, int>(lsb - 1, n + n - 1));
            res.Add(new Tuple<int, int>(n, lsb));
            res.Add(new Tuple<int, int>(n - 1, n));
            res.Add(new Tuple<int, int>(n, n - 2));
            res.Add(new Tuple<int, int>(1, n + n - 2));
        }

        Console.WriteLine("Yes");
        Console.WriteLine(string.Join("\n", res.Select(x => $"{x.Item1} {x.Item2}")));
        //Console.WriteLine(string.Join("\n", res.Select(x => $"{S(x.Item1, n)} {S(x.Item2, n)}")));
    }

    static string S(int i, int n) => i <= n ? i.ToString() : $"{i - n}_";
}

