    static void Solve(int n)
    {
        var msb = 4;
        while (msb * 2 <= n) msb *= 2;
        if (msb == n)
        {
            Console.WriteLine("No");
            return;
        }
        List<Tuple<int, int>> res = new List<Tuple<int, int>>();
        for (int i = 1; i < msb - 1; i++)
        {
            res.Add(new Tuple<int, int>(i, i + 1));
            res.Add(new Tuple<int, int>(i + n, i + n + 1));
        }
        if (res.Count > 4)
        {
            res[2] = new Tuple<int, int>(1, 3);
            res[3] = new Tuple<int, int>(1 + n, 3 + n);
        }

        res.Add(new Tuple<int, int>(msb - 1, 2 + n));

        for (int i = msb; i < n - 2; i += 2)
        {
            res.Add(new Tuple<int, int>(i, i + 1));
            res.Add(new Tuple<int, int>(i + 1, 1));
            res.Add(new Tuple<int, int>(1, i + n));
            res.Add(new Tuple<int, int>(i + n, i + 1 + n));
        }

        int lsb = (n & -n);
        res.Add(new Tuple<int, int>(n + n - 1, n + n));
        res.Add(new Tuple<int, int>(lsb - 1, n + n - 1));
        res.Add(new Tuple<int, int>(n, lsb));
        res.Add(new Tuple<int, int>(n - 1, n));
        res.Add(new Tuple<int, int>(n, n - 2));
        res.Add(new Tuple<int, int>(1, n + n - 2));

        Console.WriteLine("Yes");
        Console.WriteLine(string.Join("\n", res.Select(x => $"{x.Item1} {x.Item2}")));
        //Console.WriteLine(string.Join("\n", res.Select(x => $"{S(x.Item1, n)} {S(x.Item2, n)}")));
    }

    static string S(int i, int n) => i <= n ? i.ToString() : $"{i - n}_";
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{

	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
    int twoPowMemo = 1;
    bool answer = true;
    for(int i = 0; i < 26; i++)
    {
      if(n == twoPowMemo) answer = false;
      twoPowMemo *= 2;//2のk乗を先にメモ
    }

    if(!answer)
    {
      Console.WriteLine("No");
    }else
    {
      Console.WriteLine("Yes");

      int[][] answers = new int[2*n-1][];
      int answerCount = 0;
      for(int i = 0; i < 2*n-1; i++) answers[i] = new int[2];

      answers[answerCount][0] = n+1;
      answers[answerCount][1] = 2;
      answerCount++;

      for(int i = 0; i < (n-1)/2; i++)
      {
        answers[answerCount][0] = 2*(i+1);
        answers[answerCount][1] = 2*(i+1)+1;
        answerCount++;

        answers[answerCount][0] = 2*(i+1)+1;
        answers[answerCount][1] = 1;
        answerCount++;

        answers[answerCount][0] = 2*(i+1)+n;
        answers[answerCount][1] = 1;
        answerCount++;

        answers[answerCount][0] = 2*(i+1)+n;
        answers[answerCount][1] = 2*(i+1)+n+1;
        answerCount++;
      }

      if(n%2 == 0)
      {
        int digitMemo = 0;
        while(true)
        {
          digitMemo++;

          if((n & (1<<digitMemo)) != 0)
          {
            answers[answerCount][0] = n;
            answers[answerCount][1] = (n^(1<<digitMemo))+n;
            answerCount++;

            answers[answerCount][0] = 2*n;
            answers[answerCount][1] = (1<<digitMemo)+1;
            answerCount++;

            break;
          }
        }
      }

      var answerText = new StringBuilder();
      for(long i = 0; i < answers.Length; i++)
      {
        answerText.AppendLine(string.Join(" ", answers[i]));
      }
      Console.Write(answerText);
    }

	}
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace AGC35
{
    class Program3
    {
        static void Main()
        {
            var N = int.Parse(Console.ReadLine());

            if (IsPowerOfTwo(N))
            {
                Console.WriteLine("No");
                return;
            }

            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            Console.WriteLine("Yes");
            var p = GetPowerOfTwo(N);
            var twoP = (int)Math.Pow(2, p);
            for (int i = 1; i < (twoP - 1) * 2; i++)
                Console.WriteLine(i + " " + (i + 1));

            Console.WriteLine(((twoP + 1) * 2) + " " + (twoP) * 2);
            Console.WriteLine((twoP) * 2 + " 1");
            Console.WriteLine("1 " + (twoP + 1));
            Console.WriteLine((twoP + 1) + " " + (twoP));
            for (int i = twoP + 2; i <= N; i++)
            {
                Console.WriteLine((i - twoP) + " " + i);
                Console.WriteLine((i * 2) + " " + (i - 1));
            }

            Console.Out.Flush();
        }

        static bool IsPowerOfTwo(int num)
        {
            if (num <= 0)
                return false;
            return (num & (num - 1)) == 0;
        }

        static int GetPowerOfTwo(int num)
        {
            var p = 0;
            while (num <= 1)
            {
                num >>= 1;
                p++;
            }

            return p;
        }
    }
}

