        static public void Solve()
        {
            var N = NN;
            var two = new long[] { 1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536 };
            if (N < 3 || two.Contains(N))
            {
                Console.WriteLine("No");
                return;
            }
            if (N % 2 == 0)
            {
                var ok = true;
                var chk = N;
                var one = false;
                var firstOne = 0L;
                var firstOneTmp = 1L;
                while (chk > 0)
                {
                    if ((chk & 1) != 0)
                    {
                        if (!one)
                        {
                            firstOne = firstOneTmp;
                        }
                        one = true;
                    }
                    else
                    {
                        if (one)
                        {
                            ok = false;
                            break;
                        }
                    }
                    firstOneTmp <<= 1;
                    chk >>= 1;
                }
                if (!ok)
                {
                    Console.WriteLine("No");
                    return;
                }
                Console.WriteLine("Yes");
                var limary = two.Where(e => e < N).ToArray();
                for (var i = 0; i < limary.Length - 2; i++)
                {
                    Console.WriteLine($"{limary[i]} {limary[i + 1]}");
                }
                Console.WriteLine($"{limary[limary.Length - 2]} {limary.Last() - 1}");
                Console.WriteLine($"{limary.Last() - 1} {limary[0] + N}");
                for (var i = 0; i < limary.Length - 2; i++)
                {
                    Console.WriteLine($"{limary[i] + N} {limary[i + 1] + N}");
                }
                Console.WriteLine($"{limary[limary.Length - 2] + N} {limary.Last() - 1 + N}");
                var nextary = Range(1, limary.Last() - 1).Where(e => !limary.Contains(e)).ToArray();
                Console.WriteLine($"{limary.Last() - 1 + N} {nextary[0]}");
                for (var i = 0; i < nextary.Length - 2; i++)
                {
                    Console.WriteLine($"{nextary[i]} {nextary[i + 1]}");
                }
                Console.WriteLine($"{nextary[nextary.Length - 2]} {nextary[0] + N}");
                for (var i = 0; i < nextary.Length - 2; i++)
                {
                    Console.WriteLine($"{nextary[i] + N} {nextary[i + 1] + N}");
                }
                for (var i = limary.Last(); i < N - 1; i++)
                {
                    Console.WriteLine($"{i} {i + 1}");
                }
                Console.WriteLine($"{N - 1} {limary.Last() + N}");
                for (var i = limary.Last(); i < N - 1; i++)
                {
                    Console.WriteLine($"{i + N} {i + 1 + N}");
                }
                Console.WriteLine($"{limary.Last() - 1} {limary.Last()}");
                Console.WriteLine($"{N} {limary.Last()}");
                Console.WriteLine($"{N * 2} {firstOne}");
                return;
            }
            Console.WriteLine("Yes");
            if (N % 4 == 1)
            {
                var lim = two.Where(e => e < N).Last();
                for (var i = 1; i < lim - 1; i++)
                {
                    Console.WriteLine($"{i} {i + 1}");
                }
                Console.WriteLine($"{lim - 1} {N + 1}");
                var baseNum = N + 1;
                for (var i = 1; i < lim - 1; i++)
                {
                    Console.WriteLine($"{baseNum} {baseNum + 1}");
                    ++baseNum;
                }
                for (var i = lim; i < N; i++)
                {
                    Console.WriteLine($"{i} {i + 1}");
                }
                ++baseNum;
                Console.WriteLine($"{N} {1}");
                Console.WriteLine($"{1} {baseNum}");
                for (var i = lim; i < N; i++)
                {
                    Console.WriteLine($"{baseNum} {baseNum + 1}");
                    ++baseNum;
                }
            }
            else
            {
                for (var i = 1; i < 2 * N; i++)
                {
                    Console.WriteLine($"{i} {i + 1}");
                }
            }
        }

