        static public void Solve()
        {
            var N = NN;
            var two = new long[] { 1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536 };
            if (N < 3 || two.Contains(N))
            {
                Console.WriteLine("No");
                return;
            }
            Console.WriteLine("Yes");

            Console.WriteLine($"{N + 1} 2");
            Console.WriteLine("2 3");
            Console.WriteLine("3 1");
            Console.WriteLine($"1 {N + 2}");
            Console.WriteLine($"{N + 2} {N + 3}");

            for (var i = 4; i < N; i += 2)
            {
                Console.WriteLine($"{i} {i + 1}");
                Console.WriteLine($"{i + 1} {1}");
                Console.WriteLine($"{1} {N + i}");
                Console.WriteLine($"{N + i} {N + i + 1}");
            }
            if (N % 2 == 0)
            {
                var maxtwo = two.Where(e => e < N).Last();
                if (maxtwo % 2 == 0)
                {
                    Console.WriteLine($"{N} {maxtwo + N}");
                    Console.WriteLine($"{2 * N} {(N ^ 1) ^ maxtwo}");
                }
                else
                {
                    Console.WriteLine($"{N} {maxtwo}");
                    Console.WriteLine($"{2 * N} {((N ^ 1) ^ maxtwo) + N}");
                }
            }
        }

