namespace AtTest.AGC_035
{
    class C
    {
        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false };
            SetOut(sw);

            Method(args);

            Out.Flush();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            int bitCnt = 0;
            int now = 1;
            while (now <= n)
            {
                if ((n & now) > 0) bitCnt++;
                now *= 2;
            }

            if (bitCnt == 1)
            {
                WriteLine("No");
                return;
            }

            WriteLine("Yes");

            WriteLine("1 2");
            WriteLine("2 3");
            WriteLine(3+" "+(n+1));
            WriteLine((n+1)+" "+(n+2));
            WriteLine((n+2)+" "+(n+3));

            for(int i = 4; i + 1 <= n; i += 2)
            {
                WriteLine(i + " " + (i + 1));
                WriteLine((i + 1) + " " + (1 + n));
                WriteLine((1 + n) + " " + (i + n));
                WriteLine((i + n) + " " + (i + 1 + n));
            }

            if (n % 2 == 0)
            {
                int first = 1;
                while ((n & first) == 0) first *= 2;

                WriteLine(n + " " + (first + 1));
                WriteLine((2 * n) + " " + (n + (n ^ first)));
            }
        }

