void solve(){
	int n = read.to!int;

	for(int k = 0, m = 1; m <= n; k += 1, m *= 2){ 
		if(m == n){
			"No".writeln;
			return;
		}
	}
	"Yes".writeln;

	int[2][] ans;
	int[int] memo; // n + i をつなげた親が memo[i]
	for(int k = 0, m = 1; m <= n; k += 1, m *= 2){ 
		if(m > 1) ans ~= [m / 2, m];

		ans ~= [n + m + 1, n + m];
		memo[m] = m;

		for(int i = m + 1; i < m * 2 && i <= n; i ++){
			ans ~= [m, i];
			if(i - m / 2 < m) ans ~= [i - m / 2, n + i], memo[i] = i - m / 2;
			else ans ~= [memo[i - m], n + i], memo[i] = memo[i - m];
		} 
	}

	foreach(an; ans){
		writeln(an[0], " ", an[1]);
	}


}

