def is_2power(n: int)->bool:
    a = 1
    while a < n:
        a <<= 1
    return a == n


def skolem_xor_tree(N: int)->list:
    if is_2power(N):
        return []

    res = [
        (1, 2),
        (2, 3),
        (3, N+1),
        (N+1, N+2),
        (N+2, N+3),
    ]

    for a in range(4, N+(N % 2), 2):
        res.append((1, a))
        res.append((a, a+1))

        res.append((1, N+a+1))
        res.append((N+a+1, N+a))

    if N % 2 == 0:
        a = N ^ 1
        b = None
        for i in range(2, N):
            if (a ^ i) < N:
                a = a ^ i
                b = i
                break

        if not b:
            raise Exception()

        if a < N and a % 2 == 1:
            a += N

        if b < N and b % 2 == 1:
            b += N

        res.append((a, N))
        res.append((b, N+N))

    return res


