def is_2power(n: int)->bool:
    a = 1
    while a < n:
        a <<= 1
    return a == n


def skolem_xor_tree(N: int)->list:
    if not is_2power(N+1) or N == 1:
        return []

    return [(a, a+1) for a in range(1, 2*N)]


