    for i in 1..s {
        ans.push((row[i - 1], row[i]));
        ans.push((row[i - 1] + n, row[i] + n));
    }

    ans.push((row[s - 1], row[0] + n));
    if w + 2 <= n {
        ans.push((w + 1, 1));
        ans.push((w + 1, w + 2));

        ans.push((w + 2 + n, 1));
        ans.push((w + 2 + n, w + 1 + n));
