fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
    }
    if n.is_power_of_two() {
        puts!("No\n");
        return;
    }
    puts!("Yes\n");
    assert!(n >= 3);
    let mut p = 2;
    let mut edges = vec![];
    while p < n {
        edges.extend_from_slice(&[(1, p), (p, p + 1), (1, p + n + 1), (p + n, p + n + 1)]);
        p += 2;
    }
    if p == n {
        // realise n as ? ^ 1 ^ ?
        let mut q = 1;
        while q < n {
            q *= 2;
        }
        q /= 2;
        let other = n ^ q ^ 1;
        // q ^ 1 ^ other
        edges.extend_from_slice(&[(n, q), (other + n, 2 * n)]);
    }
    edges.push((3, 1 + n));
    assert_eq!(edges.len(), 2 * n - 1);
    for &(a, b) in &edges {
        puts!("{} {}\n", a, b);
    }
}

