    }

    if total_xor == 0 {
        sc.write("Yes\n");
        for i in 2..=n {
            sc.write(format!("{} {}\n", i - 1, i));
            sc.write(format!("{} {}\n", i - 1 + n, i + n));
        }
        sc.write(format!("{} {}\n", n, n + 1));
        return;
    }

    let mut xor_edges = BTreeSet::new();
    if total_xor.count_ones() == 1 {
        if total_xor == n {
            println!("No");
            return;
        }

        if total_xor == 1 {
            assert!(n >= 3);
            xor_edges.insert(2);
            xor_edges.insert(3);
        } else {
            xor_edges.insert(total_xor + 1);
            xor_edges.insert(1);
        }
    } else {
        for i in 0..64 {
            let k = 1 << i;
            if k & total_xor == 0 {
                continue;
            }
            assert!(k <= n);
            xor_edges.insert(k);
        }
    }

    sc.write("Yes\n");
    let mut ans = vec![total_xor];
    for &i in xor_edges.iter() {
