        row.push(3);
    }
    row.push(2);
    for i in 4..w {
        row.push(i);
    }
    let s = row.len();
    let mut ans = vec![];
    for i in 1..s {
        ans.push((row[i - 1], row[i]));
        ans.push((row[i - 1] + n, row[i] + n));
    }

