    input! {
        n: usize,
    };

    let mut nn = n;
    while nn > 1 && nn % 2 == 0 {
        nn /= 2;
    }
    if nn == 1 {
        println!("No");
        return;
    }


    let mut edges = vec![];
    edges.push((1, 2));
    edges.push((2, 3));
    edges.push((3, n+1));
    edges.push((n+1, n+2));
    edges.push((n+2, n+3));

    let mut k = 5;
    while k <= n {
        let l = k-1;
        edges.push((1, l));
        edges.push((l, k));
        edges.push((1, n+k));
        edges.push((n+k, n+l));
        k += 2;
    }
    if n % 2 == 0 {
        let mut w = 2;
        loop {
            if n & w == w {
                let c = n - w;
                edges.push((w, n));
                edges.push((n+c+1, 2*n));
                break;
            }
        }
    }

    println!("Yes");
    for &e in &edges {
        println!("{} {}", e.0, e.1);
    }
}

