fn get_pair(i: usize, n: usize) -> usize {
    if i <= n {
        i + n
    } else {
        i - n
    }
}

fn main() {
    let n = read::<usize>();
    let mut index = 1;
    while n >= index {
        if n == index {
            println!("No");
            return;
        }
        index *= 2;
    }
    println!("Yes");

    let mut max_full_bit = 1;
    while n >= 2 * max_full_bit - 1 {
        max_full_bit *= 2;
    }
    max_full_bit -= 1;

    let mut pairs = vec![];
    for i in 1..3 {
        pairs.push((i, i + 1));
    }
    pairs.push((1, get_pair(3, n)));
    for i in 1..3 {
        pairs.push((get_pair(i, n), get_pair(i + 1, n)));
    }

    if n % 2 == 1 {
        for i in 4..n + 1 {
            if i % 2 == 0 {
                pairs.push((1, i));
                pairs.push((i, i + 1));
                pairs.push((1, get_pair(i + 1, n)));
                pairs.push((get_pair(i, n), get_pair(i + 1, n)));
            }
        }
    } else {
        for i in 4..n + 1 {
            if i % 2 == 0 {
                pairs.push((1, i));
                pairs.push((i, i + 1));
                pairs.push((1, get_pair(i + 1, n)));
                pairs.push((get_pair(i, n), get_pair(i + 1, n)));
            }
        }

        let mut one_pairs = HashSet::new();
        for &(a, b) in pairs.iter() {
            if a == 1 {
                one_pairs.insert(b);
            } else if b == 1 {
                one_pairs.insert(a);
            }
        }

        if one_pairs.contains(&(max_full_bit + 1)) {
            pairs.push((max_full_bit + 1, n));
        } else {
            pairs.push((n + max_full_bit + 1, n));
        }

        if one_pairs.contains(&(max_full_bit + 1)) {
            pairs.push((n - max_full_bit, 2 * n));
        } else {
            pairs.push((2 * n - max_full_bit, 2 * n));
        }
    }

    for pair in pairs {
        println!("{0} {1}", pair.0, pair.1);
    }
}

