fn solve(n: usize) {
    if n.count_ones() == 1 {
        println!("No");
        return;
    }
    let max_bit = n.next_power_of_two() / 2;
    let mut anss: Vec<(usize, usize)> = vec![];
    for i in 1..max_bit - 1 {
        anss.push((i, i + 1));
    }
    for i in 1..max_bit - 1 {
        let prev = if i == 1 { n + 1 } else { n + (i ^ 1) };
        let next = n + ((i + 1) ^ 1);
        anss.push((prev, next));
    }
    anss.push((1, max_bit));
    anss.push((1, max_bit + 1));
    anss.push((n + 1, n + max_bit));
    anss.push((n + 1, n + 1 + max_bit));
    anss.push((max_bit, n + 1 + max_bit));
    for i in (max_bit + 2)..n + 1 {
        let prev = max_bit ^ (i % 2) ^ (i % 4 / 2);
        anss.push((prev, i));
        let next = (i - max_bit) / 2 * 2;
        anss.push((next, i + n));
    }
    println!("Yes");
    for ans in anss.iter() {
        println!("{} {}", ans.0, ans.1);
    }
    assert!(validate(n, &anss));
}

