                continue;
            }
            other.push(i);
        }
        let mut set = set.into_iter().collect::<Vec<_>>();
        set.sort();
        set.reverse();
        other.sort();

        println!("Yes");
        for i in 1..set.len() {
            println!("{} {}", set[i - 1], set[i]);
            println!("{} {}", set[i - 1] + n, set[i] + n);
        }
        for i in 1..other.len() {
            println!("{} {}", other[i - 1], other[i]);
            println!("{} {}", other[i - 1] + n, other[i] + n);
        }

        println!("{} {}", set[set.len() - 1], other[0]);
        println!("{} {}", set[0] + n, other[other.len() - 1]);
        println!("{} {}", set[set.len() - 1] + n, other[0] + n);
        println!("{} {}", n, set[0]);
        println!("{} {}", 2 * n, set[set.len() - 1]);
        println!("1 2");
        println!("3 {}", n + 1);
    } else {
        unreachable!()
    }
