    while n >= index {
        if n == index {
            println!("No");
            return;
        }
        index *= 2;
    }
    println!("Yes");

    let mut max_full_bit = 1;
    while n >= 2 * max_full_bit - 1 {
        max_full_bit *= 2;
    }
    max_full_bit -= 1;

    let mut pairs = vec![];
    for i in 1..max_full_bit {
        pairs.push((i, i + 1));
    }
    pairs.push((1, n + max_full_bit));
    for i in n + 1..n + max_full_bit {
        pairs.push((i, i + 1));
    }

    if n % 2 == 1 {
        for i in max_full_bit + 1..n {
            if (i - max_full_bit - 1) % 2 == 0 {
                pairs.push((1, i));
                pairs.push((i, i + 1));
            }
        }
        for i in n + max_full_bit + 1..2 * n {
            if (i - n - max_full_bit - 1) % 2 == 0 {
                pairs.push((1, i + 1));
                pairs.push((i, i + 1));
            }
        }
    } else {
        for i in max_full_bit + 1..n - 1 {
            if (i - max_full_bit - 1) % 2 == 0 {
                pairs.push((1, i));
                pairs.push((i, i + 1));
