                pairs.push((1, i + 1));
                pairs.push((i, i + 1));
            }
        }
        pairs.push((max_full_bit + 1, n));

        let mut one_pairs = HashSet::new();
        for &(a, b) in pairs.iter() {
            if a == 1 {
                one_pairs.insert(b);
            } else if b == 1 {
                one_pairs.insert(a);
