        }

        if one_pairs.contains(&(2 * n - max_full_bit)) {
            pairs.push((2 * n - max_full_bit, 2 * n));
        } else {
            assert!(one_pairs.contains(&(n - max_full_bit)));
            pairs.push((max_full_bit + 1, 2 * n));
