        println!("{0} {1}", i, i + 1);
    }
    for i in max_full_bit + 1..n {
        if (i - max_full_bit - 1) % 2 == 0 {
            println!("1 {0}", i);
            println!("{0} {1}", i, i + 1);
        }
    }
    for i in n + max_full_bit + 1..2 * n {
        if (i - n - max_full_bit - 1) % 2 == 0 {
            println!("1 {0}", i + 1);
            println!("{0} {1}", i + 1, i);
        }
    }
}

