fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (writeln!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
    }
    if n <= 2 {
        return puts!("{}", "No");
    }

    let mut tmp = 1;
    while 2*tmp - 1 <= n {
        tmp *= 2;
    }
    tmp -= 1;
    if (n - tmp) % 2 == 1 {
        return puts!("{}", "No");
    }

    let mut ans = vec![];
    for i in 1..tmp {
        ans.push((i, i+1));
    }
    let mut prev = tmp;
    for i in 1..tmp+1 {
        ans.push((prev, n+i));
        prev = n+i;
    }

    for i in 0..(n-tmp)/2 {
        let v1 = tmp + 2*i + 1;
        let v2 = tmp + 2*i + 2;

        ans.push((1, v1));
        ans.push((v1, v2));

        ans.push((1, v2 + n));
        ans.push((v2, v1 + n));
    }


    puts!("{}", "Yes");
    for a in ans {
        puts!("{} {}", a.0, a.1);
    }
}

